-- =========================================================================
-- Flyway Migration V15: Gender-Specific Dressing & Bilingual Integration
-- Source of Truth: SELFIDO Task Analysis Document
-- =========================================================================

-- 1. Schema Alterations for Activities and Task Steps
ALTER TABLE activities ADD COLUMN starting_position VARCHAR(500) NULL AFTER target_gender;
ALTER TABLE activities ADD COLUMN starting_position_ta TEXT NULL AFTER starting_position;
ALTER TABLE activities ADD COLUMN title_ta VARCHAR(150) NULL AFTER title;
ALTER TABLE activities ADD COLUMN description_ta TEXT NULL AFTER description;

ALTER TABLE task_steps ADD COLUMN title_ta VARCHAR(150) NULL AFTER title;
ALTER TABLE task_steps ADD COLUMN instruction_text_ta TEXT NULL AFTER instruction_text;
ALTER TABLE task_steps ADD COLUMN child_instruction_ta TEXT NULL AFTER child_instruction;
ALTER TABLE task_steps ADD COLUMN audio_prompt_url_ta VARCHAR(500) NULL AFTER audio_prompt_url;

-- 2. Scope Enforcement: Deactivate Grooming and Handwashing as per approved SELFIDO ADL scope
UPDATE activities SET is_active = FALSE WHERE id IN (14, 15);

-- 3. Update Existing Activities (1 to 13) with Gender Scoping, Starting Positions, and Tamil Translations
UPDATE activities SET category_id = 1, title = 'T-Shirt', target_gender = 'BOYS', icon_url = 'ic_tshirt', description = 'Putting on a standard round-neck T-shirt step by step.', starting_position = 'T-shirt is placed in front of the child with the front side facing upward.', title_ta = 'டி-சர்ட்', description_ta = 'வட்டக் கழுத்து டி-சர்ட்டை முறையாக அணிதல்.', starting_position_ta = 'டி-சர்ட் குழந்தையின் முன் முன்புறம் மேல்நோக்கி வைக்கப்பட்டுள்ளது.', is_active = TRUE WHERE id = 1;
UPDATE activities SET category_id = 1, title = 'Shirt', target_gender = 'BOYS', icon_url = 'ic_shirt', description = 'Putting on a button-down shirt.', starting_position = 'Shirt is placed flat with the front side facing upward and buttons undone. Stand or sit in front of the shirt.', title_ta = 'சட்டை', description_ta = 'பொத்தான்கள் கொண்ட சட்டையை அணிதல்.', starting_position_ta = 'சட்டை பொத்தான்கள் திறக்கப்பட்டு முன்புறம் மேல்நோக்கி வைக்கப்பட்டுள்ளது. சட்டைக்கு முன் நிற்கவும் அல்லது அமரவும்.', is_active = TRUE WHERE id = 2;
UPDATE activities SET category_id = 1, title = 'Zip-Up Jacket', target_gender = 'BOYS', icon_url = 'ic_jacket', description = 'Donning and zipping a jacket.', starting_position = 'Jacket is placed in front of the child with the front side facing upward and zipper completely open.', title_ta = 'ஜிப் ஜாக்கெட்', description_ta = 'ஜிப் கொண்ட ஜாக்கெட்டை அணிந்து ஜிப் போடுதல்.', starting_position_ta = 'ஜாக்கெட் ஜிப் முழுமையாக திறக்கப்பட்டு முன்புறம் மேல்நோக்கி வைக்கப்பட்டுள்ளது.', is_active = TRUE WHERE id = 3;
UPDATE activities SET category_id = 1, title = 'Undergarment – Vest', target_gender = 'BOYS', icon_url = 'ic_vest', description = 'Putting on an inner vest in a private changing area.', starting_position = 'Child is in a private changing area. The vest is placed within reach with the front side visible.', title_ta = 'உள்ளாடை – பனியன்', description_ta = 'தனிப்பட்ட அறையில் பனியன் உள்ளாடையை அணிதல்.', starting_position_ta = 'குழந்தை தனிப்பட்ட உடை மாற்றும் அறையில் உள்ளது. பனியன் முன்புறம் தெரியுமாறு வைக்கப்பட்டுள்ளது.', is_active = TRUE WHERE id = 4;
UPDATE activities SET category_id = 3, title = 'Trousers with Drawstring/Knot', target_gender = 'BOYS', icon_url = 'ic_trousers', description = 'Donning trousers and tying drawstring knot.', starting_position = 'Trousers are placed in front of the child with the waistband open and the front side facing upward.', title_ta = 'நாடா கொண்ட கால்சட்டை', description_ta = 'கால்சட்டை அணிந்து நாடாவை முடிச்சு போடுதல்.', starting_position_ta = 'கால்சட்டை இடுப்புப் பகுதி திறக்கப்பட்டு முன்புறம் மேல்நோக்கி வைக்கப்பட்டுள்ளது.', is_active = TRUE WHERE id = 5;
UPDATE activities SET category_id = 3, title = 'Jeans with Zipper', target_gender = 'BOYS', icon_url = 'ic_jeans', description = 'Donning jeans with button and zipper.', starting_position = 'Jeans are placed flat with the front side facing upward. The zipper is open and the button is undone.', title_ta = 'ஜிப் கொண்ட ஜீன்ஸ்', description_ta = 'பொத்தான் மற்றும் ஜிப் கொண்ட ஜீன்ஸ் அணிதல்.', starting_position_ta = 'ஜீன்ஸ் பொத்தான் மற்றும் ஜிப் திறக்கப்பட்டு முன்புறம் மேல்நோக்கி வைக்கப்பட்டுள்ளது.', is_active = TRUE WHERE id = 6;
UPDATE activities SET category_id = 3, title = 'Elastic Shorts', target_gender = 'BOYS', icon_url = 'ic_shorts', description = 'Pulling up elastic waistband shorts.', starting_position = 'Shorts are placed flat with the front side facing upward.', title_ta = 'எலாஸ்டிக் அரைக்கால் சட்டை', description_ta = 'எலாஸ்டிக் இடுப்புப் பட்டை கொண்ட அரைக்கால் சட்டை அணிதல்.', starting_position_ta = 'அரைக்கால் சட்டை முன்புறம் மேல்நோக்கி தட்டையாக வைக்கப்பட்டுள்ளது.', is_active = TRUE WHERE id = 7;
UPDATE activities SET category_id = 5, title = 'Wearing Socks', target_gender = 'ALL', icon_url = 'ic_socks', description = 'Putting on left and right socks step by step.', starting_position = 'Child is seated safely. Socks are placed in front of the child with the opening facing upward.', title_ta = 'காலுறை அணிதல்', description_ta = 'இரு கால்களிலும் காலுறைகளை முறையாக அணிதல்.', starting_position_ta = 'குழந்தை பாதுகாப்பாக அமர்ந்துள்ளது. காலுறைகள் திறப்பு மேல்நோக்கி வைக்கப்பட்டுள்ளன.', is_active = TRUE WHERE id = 8;
UPDATE activities SET category_id = 5, title = 'Velcro Shoes', target_gender = 'ALL', icon_url = 'ic_shoes', description = 'Putting on velcro shoes and securing straps.', starting_position = 'Child is seated. Shoes are placed in front with the openings accessible.', title_ta = 'வெல்க்ரோ காலணிகள்', description_ta = 'வெல்க்ரோ காலணிகளை அணிந்து பட்டையை ஒட்டுதல்.', starting_position_ta = 'குழந்தை அமர்ந்துள்ளது. காலணிகள் முன் வைக்கப்பட்டுள்ளன.', is_active = TRUE WHERE id = 9;
UPDATE activities SET category_id = 5, title = 'Shoes with Shoelaces', target_gender = 'ALL', icon_url = 'ic_shoelaces', description = 'Putting on shoes with laces and tightening.', starting_position = 'Sit in a stable position. Putting on the shoe.', title_ta = 'கயிறு கொண்ட காலணிகள்', description_ta = 'கயிறு கொண்ட காலணிகளை அணிந்து சரிசெய்தல்.', starting_position_ta = 'நிலையாக அமர்ந்து காலணியை அணியத் தொடங்கவும்.', is_active = TRUE WHERE id = 10;
UPDATE activities SET category_id = 6, title = 'Eating Rice with Gravy/Curry', target_gender = 'ALL', icon_url = 'ic_eating_hands', description = 'Mixing and eating rice with hands.', starting_position = 'Child is seated appropriately with a plate of rice and suitable gravy/curry.', title_ta = 'குழம்பு சாதம் சாப்பிடுதல்', description_ta = 'கையால் சாதமும் குழம்பும் பிசைந்து சாப்பிடுதல்.', starting_position_ta = 'குழந்தை தட்டில் சாதம் மற்றும் குழம்புடன் சரியாக அமர்ந்துள்ளது.', is_active = TRUE WHERE id = 11;
UPDATE activities SET category_id = 6, title = 'Eating Breakfast Items with Hands', target_gender = 'ALL', icon_url = 'ic_breakfast', description = 'Breaking and eating idli/dosa/roti with accompaniment.', starting_position = 'Child is seated appropriately with the breakfast item and suitable accompaniment on the plate. Sit upright at the table.', title_ta = 'சிற்றுண்டி சாப்பிடுதல்', description_ta = 'இட்லி, தோசை, சப்பாத்தி போன்றவற்றை பிய்த்து தொட்டு சாப்பிடுதல்.', starting_position_ta = 'குழந்தை தட்டில் சிற்றுண்டி மற்றும் சட்னி/சாம்பாருடன் நேராக அமர்ந்துள்ளது.', is_active = TRUE WHERE id = 12;
UPDATE activities SET category_id = 6, title = 'Eating with Spoon', target_gender = 'ALL', icon_url = 'ic_spoon', description = 'Scooping and eating food with a spoon.', starting_position = 'Child is seated upright at a table. Food is placed in a suitable bowl/plate, and a spoon is within reach.', title_ta = 'கரண்டியால் சாப்பிடுதல்', description_ta = 'கரண்டியால் உணவை அள்ளி வாயில் வைத்து சாப்பிடுதல்.', starting_position_ta = 'குழந்தை மேஜையில் நேராக அமர்ந்துள்ளது. கிண்ணத்தில் உணவும் கரண்டியும் உள்ளன.', is_active = TRUE WHERE id = 13;

-- 4. Insert New Approved Activities (16 to 27)

-- 5. Seed / Update Task Steps for All 25 Approved Activities
-- Activity 1 (20 steps)
UPDATE task_steps SET title = 'Stand or sit in front of the T-shirt', title_ta = 'டி-சர்ட்டின் முன் நிற்கவும் அல்லது அமரவும்', instruction_text = 'Ask the child to stand or sit calmly facing the T-shirt.', instruction_text_ta = 'குழந்தையை டி-சர்ட்டின் முன் நேராக நிற்க அல்லது அமர வைக்கவும்.', child_instruction = 'Stand or sit in front of your T-shirt!', child_instruction_ta = 'உன் டி-சர்ட்டின் முன்னால் அமர்ந்து பார்!' WHERE id = 1;
UPDATE task_steps SET title = 'Look at the T-shirt', title_ta = 'டி-சர்ட்டைப் பார்க்கவும்', instruction_text = 'Ask the child to focus attention on the T-shirt.', instruction_text_ta = 'குழந்தையை டி-சர்ட்டை உற்றுப் பார்க்கச் சொல்லவும்.', child_instruction = 'Look at the T-shirt carefully!', child_instruction_ta = 'டி-சர்ட்டை நன்றாகப் பார்!' WHERE id = 2;
UPDATE task_steps SET title = 'Pick up the T-shirt with both hands', title_ta = 'இரு கைகளாலும் டி-சர்ட்டை எடுக்கவும்', instruction_text = 'Child picks up the T-shirt using both hands.', instruction_text_ta = 'குழந்தை இரு கைகளாலும் டி-சர்ட்டை எடுக்க வேண்டும்.', child_instruction = 'Pick up your T-shirt with both hands!', child_instruction_ta = 'இரு கைகளாலும் டி-சர்ட்டை எடு!' WHERE id = 3;
UPDATE task_steps SET title = 'Identify the front and back of the T-shirt', title_ta = 'டி-சர்ட்டின் முன்புறம் மற்றும் பின்புறத்தை அடையாளம் காணவும்', instruction_text = 'Child identifies front graphic or back collar tag.', instruction_text_ta = 'பின்பக்க லேபிள் அல்லது முன்பக்க படத்தை அடையாளம் காணவும்.', child_instruction = 'Find the tag on the back and picture on the front!', child_instruction_ta = 'பின்பக்க லேபிளைக் கண்டுபிடி!' WHERE id = 4;
UPDATE task_steps SET title = 'Find the bottom edge of the T-shirt', title_ta = 'டி-சர்ட்டின் கீழ் விளிம்பைக் கண்டறியவும்', instruction_text = 'Child locates the lower hem opening of the T-shirt.', instruction_text_ta = 'டி-சர்ட்டின் கீழ் விளிம்புப் பகுதியைக் கண்டறியவும்.', child_instruction = 'Find the bottom opening of your shirt!', child_instruction_ta = 'சட்டையின் கீழ் விளிம்பைத் தொடு!' WHERE id = 5;
UPDATE task_steps SET title = 'Find the neck opening', title_ta = 'கழுத்துத் துவாரத்தைக் கண்டறியவும்', instruction_text = 'Child locates the main neck collar opening.', instruction_text_ta = 'முக்கிய கழுத்துப் பகுதியை அடையாளம் காணவும்.', child_instruction = 'Look for the neck hole at the top!', child_instruction_ta = 'மேலே உள்ள கழுத்துத் துவாரத்தைப் பார்!' WHERE id = 6;
UPDATE task_steps SET title = 'Hold the T-shirt at the shoulder areas', title_ta = 'தோள்பட்டைப் பகுதிகளைப் பிடிக்கவும்', instruction_text = 'Child grips the left and right shoulder seams firmly.', instruction_text_ta = 'இரு தோள்பட்டைப் பகுதியையும் கைகளால் பிடிக்கவும்.', child_instruction = 'Hold your shirt near both shoulders!', child_instruction_ta = 'தோள்பட்டைப் பகுதியை கெட்டியாகப் பிடி!' WHERE id = 7;
UPDATE task_steps SET title = 'Lift the T-shirt to chest level', title_ta = 'டி-சர்ட்டை மார்பு உயரத்திற்கு உயர்த்தவும்', instruction_text = 'Child raises the T-shirt upward toward chest level.', instruction_text_ta = 'டி-சர்ட்டை மார்பு உயரத்திற்கு தூக்கவும்.', child_instruction = 'Lift the shirt up to your chest!', child_instruction_ta = 'மார்பு உயரத்திற்கு சட்டையைத் தூக்கு!' WHERE id = 8;
UPDATE task_steps SET title = 'Put the head through the neck opening', title_ta = 'தலையை கழுத்துத் துவாரத்திற்குள் நுழைக்கவும்', instruction_text = 'Child guides head through the collar opening.', instruction_text_ta = 'தலையை கழுத்துப் பகுதி வழியே நுழைக்கவும்.', child_instruction = 'Pop your head through the neck hole! Peekaboo!', child_instruction_ta = 'தலையை உள்ளே நுழை! எட்டிப் பார்!' WHERE id = 9;
UPDATE task_steps SET title = 'Pull the T-shirt down over the head', title_ta = 'தலையைக் கடந்து கீழே இழுக்கவும்', instruction_text = 'Child pulls the collar opening down past the head onto the neck.', instruction_text_ta = 'கழுத்து வழியாக சட்டையை கீழே இழுக்கவும்.', child_instruction = 'Pull the shirt down around your neck!', child_instruction_ta = 'சட்டையைக் கழுத்துக்குக் கீழே இழு!' WHERE id = 10;
UPDATE task_steps SET title = 'Find the right sleeve opening', title_ta = 'வலது கை துவாரத்தைக் கண்டறியவும்', instruction_text = 'Child locates the right sleeve armhole.', instruction_text_ta = 'வலது கை சட்டைக் குழாயைக் கண்டறியவும்.', child_instruction = 'Find the right sleeve hole!', child_instruction_ta = 'வலது கைத் துவாரத்தைக் கண்டுபிடி!' WHERE id = 11;
UPDATE task_steps SET title = 'Put the right arm through the right sleeve', title_ta = 'வலது கையை வலது கைக்குழாயில் நுழைக்கவும்', instruction_text = 'Child pushes right hand and arm through sleeve.', instruction_text_ta = 'வலது கையை சட்டைக்குள் நுழைத்து வெளியே கொண்டு வரவும்.', child_instruction = 'Push your right arm through the sleeve!', child_instruction_ta = 'வலது கையை உள்ளே நுழை!' WHERE id = 12;
UPDATE task_steps SET title = 'Pull the right sleeve up toward the shoulder', title_ta = 'வலது கையை தோள்பட்டை வரை இழுக்கவும்', instruction_text = 'Child pulls the sleeve securely up onto the shoulder.', instruction_text_ta = 'வலது கை சட்டையை தோள்பட்டை வரை மேலே இழுக்கவும்.', child_instruction = 'Pull the sleeve up on your right shoulder!', child_instruction_ta = 'தோள்பட்டை வரை சட்டையை இழு!' WHERE id = 13;
UPDATE task_steps SET title = 'Find the left sleeve opening', title_ta = 'இடது கை துவாரத்தைக் கண்டறியவும்', instruction_text = 'Child locates the left sleeve armhole.', instruction_text_ta = 'இடது கை சட்டைக் குழாயைக் கண்டறியவும்.', child_instruction = 'Find the left sleeve hole!', child_instruction_ta = 'இடது கைத் துவாரத்தைக் கண்டுபிடி!' WHERE id = 14;
UPDATE task_steps SET title = 'Put the left arm through the left sleeve', title_ta = 'இடது கையை இடது கைக்குழாயில் நுழைக்கவும்', instruction_text = 'Child pushes left hand and arm through sleeve.', instruction_text_ta = 'இடது கையை சட்டைக்குள் நுழைத்து வெளியே கொண்டு வரவும்.', child_instruction = 'Push your left arm through the sleeve!', child_instruction_ta = 'இடது கையை உள்ளே நுழை!' WHERE id = 15;
UPDATE task_steps SET title = 'Pull the left sleeve up toward the shoulder', title_ta = 'இடது கையை தோள்பட்டை வரை இழுக்கவும்', instruction_text = 'Child pulls the left sleeve securely up onto the shoulder.', instruction_text_ta = 'இடது கை சட்டையை தோள்பட்டை வரை மேலே இழுக்கவும்.', child_instruction = 'Pull the sleeve up on your left shoulder!', child_instruction_ta = 'தோள்பட்டை வரை சட்டையை இழு!' WHERE id = 16;
