INSERT INTO activities (id, category_id, title, target_gender, icon_url, description, starting_position, title_ta, description_ta, starting_position_ta, is_active) VALUES (16, 3, 'Undergarment – Briefs', 'BOYS', 'ic_briefs', 'Putting on briefs in a private changing area.', 'Child is in a private changing area. Clean underwear is placed within reach.', 'உள்ளாடை – ஜட்டி', 'தனிப்பட்ட அறையில் ஜட்டி உள்ளாடையை அணிதல்.', 'குழந்தை தனிப்பட்ட உடை மாற்றும் அறையில் உள்ளது. சுத்தமான உள்ளாடை வைக்கப்பட்டுள்ளது.', TRUE) ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), target_gender = VALUES(target_gender), icon_url = VALUES(icon_url), description = VALUES(description), starting_position = VALUES(starting_position), title_ta = VALUES(title_ta), description_ta = VALUES(description_ta), starting_position_ta = VALUES(starting_position_ta), is_active = TRUE;
INSERT INTO activities (id, category_id, title, target_gender, icon_url, description, starting_position, title_ta, description_ta, starting_position_ta, is_active) VALUES (17, 2, 'T-Shirt', 'GIRLS', 'ic_tshirt', 'Putting on a standard T-shirt for girls.', 'T-shirt is placed flat in front of the child with the front side facing upward. Stand or sit in front of the T-shirt.', 'டி-சர்ட்', 'சிறுமிகளுக்கான டி-சர்ட்டை முறையாக அணிதல்.', 'டி-சர்ட் முன்புறம் மேல்நோக்கி தட்டையாக வைக்கப்பட்டுள்ளது. அதற்கு முன் நிற்கவும் அல்லது அமரவும்.', TRUE) ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), target_gender = VALUES(target_gender), icon_url = VALUES(icon_url), description = VALUES(description), starting_position = VALUES(starting_position), title_ta = VALUES(title_ta), description_ta = VALUES(description_ta), starting_position_ta = VALUES(starting_position_ta), is_active = TRUE;
INSERT INTO activities (id, category_id, title, target_gender, icon_url, description, starting_position, title_ta, description_ta, starting_position_ta, is_active) VALUES (18, 2, 'Front-Open Top', 'GIRLS', 'ic_top', 'Putting on a front-open button top.', 'Top is placed flat with the front side facing upward and all buttons undone.', 'முன் திறப்பு மேலாடை', 'முன் திறப்பு மற்றும் பொத்தான்கள் கொண்ட மேலாடை அணிதல்.', 'மேலாடை அனைத்து பொத்தான்களும் திறக்கப்பட்டு முன்புறம் மேல்நோக்கி வைக்கப்பட்டுள்ளது.', TRUE) ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), target_gender = VALUES(target_gender), icon_url = VALUES(icon_url), description = VALUES(description), starting_position = VALUES(starting_position), title_ta = VALUES(title_ta), description_ta = VALUES(description_ta), starting_position_ta = VALUES(starting_position_ta), is_active = TRUE;
INSERT INTO activities (id, category_id, title, target_gender, icon_url, description, starting_position, title_ta, description_ta, starting_position_ta, is_active) VALUES (19, 2, 'Zip-Up Jacket', 'GIRLS', 'ic_jacket', 'Donning and zipping a jacket for girls.', 'Jacket is placed flat with the front side facing upward and zipper completely open.', 'ஜிப் ஜாக்கெட்', 'சிறுமிகளுக்கான ஜிப் ஜாக்கெட் அணிந்து ஜிப் போடுதல்.', 'ஜாக்கெட் ஜிப் முழுமையாக திறக்கப்பட்டு முன்புறம் மேல்நோக்கி தட்டையாக வைக்கப்பட்டுள்ளது.', TRUE) ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), target_gender = VALUES(target_gender), icon_url = VALUES(icon_url), description = VALUES(description), starting_position = VALUES(starting_position), title_ta = VALUES(title_ta), description_ta = VALUES(description_ta), starting_position_ta = VALUES(starting_position_ta), is_active = TRUE;
INSERT INTO activities (id, category_id, title, target_gender, icon_url, description, starting_position, title_ta, description_ta, starting_position_ta, is_active) VALUES (20, 2, 'Pullover Frock', 'GIRLS', 'ic_frock', 'Putting on a pullover frock.', 'Frock is placed flat with the front side facing upward.', 'பிராக் கவுன்', 'பிராக் கவுன் ஆடையை அணிதல்.', 'பிராக் ஆடை முன்புறம் மேல்நோக்கி தட்டையாக வைக்கப்பட்டுள்ளது.', TRUE) ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), target_gender = VALUES(target_gender), icon_url = VALUES(icon_url), description = VALUES(description), starting_position = VALUES(starting_position), title_ta = VALUES(title_ta), description_ta = VALUES(description_ta), starting_position_ta = VALUES(starting_position_ta), is_active = TRUE;
INSERT INTO activities (id, category_id, title, target_gender, icon_url, description, starting_position, title_ta, description_ta, starting_position_ta, is_active) VALUES (21, 2, 'Undergarment – Camisole', 'GIRLS', 'ic_camisole', 'Putting on a camisole in a private changing area.', 'Child is in a private changing area. The clean vest/camisole is placed within reach with the front side visible.', 'உள்ளாடை – கேமிசோல்', 'தனிப்பட்ட அறையில் கேமிசோல் உள்சட்டை அணிதல்.', 'குழந்தை தனிப்பட்ட உடை மாற்றும் அறையில் உள்ளது. சுத்தமான கேமிசோல் வைக்கப்பட்டுள்ளது.', TRUE) ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), target_gender = VALUES(target_gender), icon_url = VALUES(icon_url), description = VALUES(description), starting_position = VALUES(starting_position), title_ta = VALUES(title_ta), description_ta = VALUES(description_ta), starting_position_ta = VALUES(starting_position_ta), is_active = TRUE;
INSERT INTO activities (id, category_id, title, target_gender, icon_url, description, starting_position, title_ta, description_ta, starting_position_ta, is_active) VALUES (22, 4, 'Drawstring Skirt', 'GIRLS', 'ic_skirt', 'Donning skirt and tying drawstring knot.', 'Skirt is placed flat in front of the child with the front side facing upward and the drawstring untied/loose.', 'நாடா பாவாடை', 'நாடா கொண்ட பாவாடை அணிந்து முடிச்சு போடுதல்.', 'பாவாடை நாடா அவிழ்க்கப்பட்டு முன்புறம் மேல்நோக்கி வைக்கப்பட்டுள்ளது.', TRUE) ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), target_gender = VALUES(target_gender), icon_url = VALUES(icon_url), description = VALUES(description), starting_position = VALUES(starting_position), title_ta = VALUES(title_ta), description_ta = VALUES(description_ta), starting_position_ta = VALUES(starting_position_ta), is_active = TRUE;
INSERT INTO activities (id, category_id, title, target_gender, icon_url, description, starting_position, title_ta, description_ta, starting_position_ta, is_active) VALUES (23, 4, 'Elastic Shorts', 'GIRLS', 'ic_shorts', 'Pulling up elastic shorts for girls.', 'Shorts are placed flat with the front side facing upward.', 'எலாஸ்டிக் அரைக்கால் சட்டை', 'சிறுமிகளுக்கான எலாஸ்டிக் அரைக்கால் சட்டை அணிதல்.', 'அரைக்கால் சட்டை முன்புறம் மேல்நோக்கி தட்டையாக வைக்கப்பட்டுள்ளது.', TRUE) ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), target_gender = VALUES(target_gender), icon_url = VALUES(icon_url), description = VALUES(description), starting_position = VALUES(starting_position), title_ta = VALUES(title_ta), description_ta = VALUES(description_ta), starting_position_ta = VALUES(starting_position_ta), is_active = TRUE;
INSERT INTO activities (id, category_id, title, target_gender, icon_url, description, starting_position, title_ta, description_ta, starting_position_ta, is_active) VALUES (24, 4, 'Jeans with Zipper', 'GIRLS', 'ic_jeans', 'Donning jeans with button and zipper for girls.', 'Jeans are placed flat with the front side facing upward, zipper open, and button undone.', 'ஜிப் கொண்ட ஜீன்ஸ்', 'சிறுமிகளுக்கான ஜிப் மற்றும் பொத்தான் ஜீன்ஸ் அணிதல்.', 'ஜீன்ஸ் ஜிப் மற்றும் பொத்தான் திறக்கப்பட்டு முன்புறம் மேல்நோக்கி வைக்கப்பட்டுள்ளது.', TRUE) ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), target_gender = VALUES(target_gender), icon_url = VALUES(icon_url), description = VALUES(description), starting_position = VALUES(starting_position), title_ta = VALUES(title_ta), description_ta = VALUES(description_ta), starting_position_ta = VALUES(starting_position_ta), is_active = TRUE;
INSERT INTO activities (id, category_id, title, target_gender, icon_url, description, starting_position, title_ta, description_ta, starting_position_ta, is_active) VALUES (25, 4, 'Undergarment – Panties/Briefs', 'GIRLS', 'ic_panties', 'Putting on panties in a private changing area.', 'Child is in a private changing area. Clean underwear is placed within reach.', 'உள்ளாடை – பேண்டீஸ்', 'தனிப்பட்ட அறையில் பேண்டீஸ் உள்ளாடையை அணிதல்.', 'குழந்தை தனிப்பட்ட உடை மாற்றும் அறையில் உள்ளது. சுத்தமான உள்ளாடை வைக்கப்பட்டுள்ளது.', TRUE) ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), target_gender = VALUES(target_gender), icon_url = VALUES(icon_url), description = VALUES(description), starting_position = VALUES(starting_position), title_ta = VALUES(title_ta), description_ta = VALUES(description_ta), starting_position_ta = VALUES(starting_position_ta), is_active = TRUE;
INSERT INTO activities (id, category_id, title, target_gender, icon_url, description, starting_position, title_ta, description_ta, starting_position_ta, is_active) VALUES (26, 5, 'Wearing Shoes – Slip-On Shoes', 'ALL', 'ic_slipon', 'Putting on slip-on shoes without laces or straps.', 'Sit in a stable position and look at the shoes.', 'ஸ்லிப்-ஆன் காலணிகள்', 'கயிறு அல்லது பட்டை இல்லாத ஸ்லிப்-ஆன் காலணிகள் அணிதல்.', 'நிலையாக அமர்ந்து காலணிகளைப் பார்க்கவும்.', TRUE) ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), target_gender = VALUES(target_gender), icon_url = VALUES(icon_url), description = VALUES(description), starting_position = VALUES(starting_position), title_ta = VALUES(title_ta), description_ta = VALUES(description_ta), starting_position_ta = VALUES(starting_position_ta), is_active = TRUE;
INSERT INTO activities (id, category_id, title, target_gender, icon_url, description, starting_position, title_ta, description_ta, starting_position_ta, is_active) VALUES (27, 5, 'Shoelace Tying', 'ALL', 'ic_shoelaces', 'Tying shoe laces with loops and knot.', 'Find both laces and hold one lace in each hand.', 'காலணிக் கயிறு கட்டுதல்', 'காலணிக் கயிற்றை சுருக்குப் போட்டு முடிச்சு கட்டுதல்.', 'இரண்டு கயிறுகளையும் கண்டுபிடித்து கைகளில் பிடிக்கவும்.', TRUE) ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), target_gender = VALUES(target_gender), icon_url = VALUES(icon_url), description = VALUES(description), starting_position = VALUES(starting_position), title_ta = VALUES(title_ta), description_ta = VALUES(description_ta), starting_position_ta = VALUES(starting_position_ta), is_active = TRUE;
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (19, 1, 19, 'Straighten the T-shirt around the shoulders and waist', 'தோள்பட்டை மற்றும் இடுப்பில் நேராக்கவும்', 'Child adjusts and straightens fabric across shoulders and waist.', 'தோள்பட்டை மற்றும் இடுப்பில் உள்ள சுருக்கங்களை சரிசெய்யவும்.', 'Straighten your shirt nicely!', 'சட்டையை நேராக சரிசெய்!') ON DUPLICATE KEY UPDATE title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (20, 1, 20, 'Check that the T-shirt is worn comfortably and correctly', 'டி-சர்ட் வசதியாகவும் சரியாகவும் உள்ளதா என சரிபார்க்கவும்', 'Child inspects fit in mirror or looks down to ensure comfort.', 'சட்டை வசதியாக உள்ளதா என சரிபார்த்து மகிழவும்.', 'Look in the mirror! You look great in your T-shirt!', 'கண்ணாடியில் பார்! அருமையாக உள்ளது!') ON DUPLICATE KEY UPDATE title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (201, 2, 1, 'Look at the shirt', 'சட்டையைப் பார்க்கவும்', 'Child focuses attention on the shirt placed flat.', 'குழந்தையை தட்டையாக வைக்கப்பட்டுள்ள சட்டையைப் பார்க்கச் சொல்லவும்.', 'Look at your nice shirt!', 'உன் சட்டையை நன்றாகப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (202, 2, 2, 'Pick up the shirt with both hands', 'இரு கைகளாலும் சட்டையை எடுக்கவும்', 'Child picks up the shirt holding with both hands.', 'இரு கைகளாலும் சட்டையை எடுக்கவும்.', 'Pick up your shirt with two hands!', 'இரு கைகளாலும் சட்டையை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (203, 2, 3, 'Identify the front and back of the shirt', 'முன்புறம் மற்றும் பின்புறத்தை அடையாளம் காணவும்', 'Child identifies collar and front buttons.', 'முன்பக்க பொத்தான்கள் மற்றும் காலரை அடையாளம் காணவும்.', 'Find the buttons in the front!', 'முன்பக்க பொத்தான்களைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (204, 2, 4, 'Identify the collar/neck opening', 'காலர்/கழுத்துத் துவாரத்தை அடையாளம் காணவும்', 'Child locates the top collar area.', 'சட்டையின் காலர் பகுதியை அடையாளம் காணவும்.', 'Find the shirt collar!', 'சட்டையின் காலரைத் தொடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (205, 2, 5, 'Hold the shirt by the shoulder areas', 'தோள்பட்டைப் பகுதிகளைப் பிடிக்கவும்', 'Child holds shirt firmly by both shoulder seams.', 'தோள்பட்டைப் பகுதிகளை உறுதியாகப் பிடிக்கவும்.', 'Hold the shirt at the shoulders!', 'தோள்பட்டையில் சட்டையைப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (206, 2, 6, 'Put one arm into the corresponding sleeve', 'ஒரு கையை சட்டைக் குழாயில் நுழைக்கவும்', 'Child inserts dominant or preferred arm into sleeve.', 'ஒரு கையை சட்டைக் குழாயில் நுழைக்கவும்.', 'Slide your arm into the sleeve!', 'ஒரு கையை சட்டைக்குள் நுழை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (207, 2, 7, 'Pull the sleeve up toward the shoulder', 'சட்டைக் குழாயை தோள்பட்டை வரை இழுக்கவும்', 'Child pulls the sleeve securely up onto the shoulder.', 'சட்டையை தோள்பட்டை வரை மேலே இழுக்கவும்.', 'Pull the sleeve up to your shoulder!', 'தோள்பட்டை வரை சட்டையை இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (208, 2, 8, 'Put the other arm into the corresponding sleeve', 'மற்றொரு கையை அடுத்த குழாயில் நுழைக்கவும்', 'Child reaches behind or guides other arm into second sleeve.', 'மற்றொரு கையை இரண்டாவது சட்டைக் குழாயில் நுழைக்கவும்.', 'Slide your other arm into the sleeve!', 'அடுத்த கையை உள்ளே நுழை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (209, 2, 9, 'Pull the second sleeve up toward the shoulder', 'இரண்டாவது குழாயை தோள்பட்டை வரை இழுக்கவும்', 'Child pulls the second sleeve completely up.', 'இரண்டாவது சட்டையையும் தோள்பட்டை வரை மேலே இழுக்கவும்.', 'Pull that sleeve up to your shoulder too!', 'இரண்டாவது கையையும் மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (210, 2, 10, 'Pull the shirt onto both shoulders', 'சட்டையை இரு தோள்களிலும் சரியாகப் போடவும்', 'Child positions the shirt comfortably across both shoulders.', 'சட்டையை இரு தோள்களிலும் சீராகப் பொருத்தவும்.', 'Settle the shirt on both shoulders!', 'சட்டையை தோள்களில் நேராக வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (211, 2, 11, 'Straighten the shirt at the shoulders', 'தோள்பட்டையில் சட்டையை நேராக்கவும்', 'Child smooths fabric over shoulders.', 'தோள்பட்டைப் பகுதியில் உள்ள சுருக்கங்களை நீக்கவும்.', 'Smooth out your shirt at the shoulders!', 'தோள்பட்டையை மெதுவாக சரிசெய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (212, 2, 12, 'Pull the front panels down', 'முன்பக்க விளிம்புகளை கீழே இழுக்கவும்', 'Child grasps both front panels and pulls downward.', 'முன்பக்க இரு விளிம்புகளையும் கீழ்நோக்கி இழுக்கவும்.', 'Pull the front of your shirt down!', 'முன்பக்கத்தை கீழே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (213, 2, 13, 'Find the top button and corresponding buttonhole', 'முதல் பொத்தான் மற்றும் துளையைக் கண்டறியவும்', 'Child locates the highest button and its matching hole.', 'முதல் பொத்தானையும் அதன் காஜாவையும் கண்டறியவும்.', 'Find the top button and hole!', 'முதல் பொத்தானைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (214, 2, 14, 'Hold the buttonhole with one hand', 'ஒரு கையால் பொத்தான் துளையைப் பிடிக்கவும்', 'Child holds the buttonhole fabric edge steady.', 'ஒரு கையால் காஜா துணியை கெட்டியாகப் பிடிக்கவும்.', 'Hold the buttonhole steady!', 'துளையை ஒரு கையால் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (215, 2, 15, 'Hold the button with the other hand', 'மற்றொரு கையால் பொத்தானைப் பிடிக்கவும்', 'Child pinches the button using pincer grasp.', 'மற்றொரு கையால் பொத்தானை விரல்களால் பிடிக்கவும்.', 'Pinch the button with your fingers!', 'பொத்தானை விரலால் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (216, 2, 16, 'Push the button through the buttonhole', 'பொத்தானை துளைக்குள் தள்ளவும்', 'Child pushes the edge of button through the slot.', 'பொத்தானை துளைக்குள் பாதியளவு தள்ளவும்.', 'Push the button through the hole!', 'பொத்தானை துளைக்குள் தள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (217, 2, 17, 'Check that the button is secured', 'பொத்தான் மாட்டப்பட்டுள்ளதா என சரிபார்க்கவும்', 'Child pulls button through and confirms it is fastened.', 'பொத்தான் துளையில் சரியாக மாட்டப்பட்டுள்ளதா என உறுதிசெய்யவும்.', 'Pull it through! Button fastened!', 'பொத்தான் மாட்டியாச்சு! அருமை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (218, 2, 18, 'Repeat the buttoning sequence from top to bottom', 'மேலிருந்து கீழ் நோக்கி மற்ற பொத்தான்களைப் போடவும்', 'Child proceeds to next button down and aligns with hole.', 'அடுத்தடுத்த பொத்தான்களை துளைகளோடு சீராக இணைக்கவும்.', 'Button the next button down!', 'அடுத்த பொத்தானையும் மாட்டு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (219, 2, 19, 'Continue until all required buttons are fastened', 'அனைத்து பொத்தான்களையும் மாட்டி முடிக்கவும்', 'Child fastens all remaining buttons on the front placket.', 'முன்பக்க அனைத்து பொத்தான்களையும் வரிசையாக மாட்டவும்.', 'Fasten all the buttons all the way down!', 'எல்லா பொத்தான்களையும் மாட்டி முடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (220, 2, 20, 'Pull the shirt down toward the waist', 'சட்டையை இடுப்பு வரை கீழே இழுக்கவும்', 'Child pulls both front panels down flat.', 'சட்டையின் கீழ் பகுதியை இடுப்பு வரை இழுத்து விடவும்.', 'Pull your shirt down to your waist!', 'சட்டையை கீழே இழுத்து விடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (221, 2, 21, 'Straighten the collar', 'காலரை நேராக்கவும்', 'Child folds and aligns collar neatly around neck.', 'சட்டைக் காலரை நேராக மடித்து விடவும்.', 'Fix your collar nice and neat!', 'காலரை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (222, 2, 22, 'Straighten the sleeves and front panels', 'கை மற்றும் முன்பகுதியை சரிசெய்யவும்', 'Child smooths front and cuffs.', 'கைப்பகுதி மற்றும் முன்பக்கத்தை சுருக்கமின்றி சரிசெய்யவும்.', 'Smooth your sleeves and front!', 'கைகளையும் சட்டையையும் நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (223, 2, 23, 'Check that the shirt is correctly positioned and comfortable', 'சட்டை சரியாகவும் வசதியாகவும் உள்ளதா எனப் பார்க்கவும்', 'Child inspects completed shirt in mirror.', 'சட்டை முழுமையாக அழகாக உள்ளதா எனப் பார்க்கவும்.', 'Look at that! You look so handsome in your shirt!', 'அருமை! சட்டை அழகாக உள்ளது!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (301, 3, 1, 'Stand or sit in front of the jacket', 'ஜாக்கெட்டின் முன் நிற்கவும் அல்லது அமரவும்', 'Child takes stable posture facing the jacket.', 'ஜாக்கெட்டின் முன் நேராக நிற்கவும் அல்லது அமரவும்.', 'Stand or sit in front of your jacket!', 'ஜாக்கெட்டின் முன் அமர்ந்து கொள்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (302, 3, 2, 'Look at the jacket', 'ஜாக்கெட்டைப் பார்க்கவும்', 'Child observes the open jacket and components.', 'திறந்துள்ள ஜாக்கெட்டை கவனமாகப் பார்க்கவும்.', 'Look at the jacket!', 'ஜாக்கெட்டைப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (303, 3, 3, 'Pick up the jacket', 'ஜாக்கெட்டை எடுக்கவும்', 'Child lifts jacket using two hands.', 'இரு கைகளாலும் ஜாக்கெட்டை மேலே தூக்கவும்.', 'Pick up your jacket!', 'ஜாக்கெட்டை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (304, 3, 4, 'Identify the front and back', 'முன்புறம் மற்றும் பின்புறத்தை அறியவும்', 'Child distinguishes open zipper front from solid back.', 'ஜிப் உள்ள முன்புறத்தையும் பின்புறத்தையும் அடையாளம் காணவும்.', 'Find the front with the zipper!', 'ஜிப் இருக்கும் முன்பக்கத்தைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (305, 3, 5, 'Identify the collar/neck opening', 'காலர் பகுதியை அடையாளம் காணவும்', 'Child locates neck opening.', 'கழுத்து காலர் பகுதியைத் தொட்டுப் பார்க்கவும்.', 'Find the collar at the top!', 'மேலே உள்ள காலரைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (306, 3, 6, 'Hold the jacket by the shoulders', 'தோள்பட்டைப் பகுதிகளைப் பிடிக்கவும்', 'Child grips shoulders of jacket.', 'ஜாக்கெட்டின் தோள்பட்டைகளைப் பிடிக்கவும்.', 'Hold the jacket by the shoulders!', 'தோள்பட்டைகளில் ஜாக்கெட்டைப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (307, 3, 7, 'Put one arm into the corresponding sleeve', 'ஒரு கையை குழாயில் நுழைக்கவும்', 'Child slips first arm into sleeve.', 'ஒரு கையை ஜாக்கெட் குழாயில் நுழைக்கவும்.', 'Put your arm into the sleeve!', 'ஒரு கையை உள்ளே நுழை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (308, 3, 8, 'Pull the sleeve toward the shoulder', 'தோள்பட்டை வரை குழாயை இழுக்கவும்', 'Child pulls sleeve completely on.', 'கைக்குழாயை தோள்பட்டை வரை மேலே இழுக்கவும்.', 'Pull the sleeve up high!', 'தோள்பட்டை வரை இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (309, 3, 9, 'Put the other arm into the corresponding sleeve', 'மற்றொரு கையை அடுத்த குழாயில் நுழைக்கவும்', 'Child inserts second arm into other sleeve.', 'மற்றொரு கையை அடுத்த கைக்குழாயில் நுழைக்கவும்.', 'Put your other arm in the sleeve!', 'அடுத்த கையையும் உள்ளே நுழை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (310, 3, 10, 'Pull the second sleeve toward the shoulder', 'இரண்டாவது குழாயை தோள்பட்டை வரை இழுக்கவும்', 'Child pulls second sleeve up onto shoulder.', 'இரண்டாவது கையையும் தோள்பட்டை வரை மேலே இழுக்கவும்.', 'Pull this sleeve up too!', 'இதையும் மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (311, 3, 11, 'Pull the jacket onto both shoulders', 'ஜாக்கெட்டை இரு தோள்களிலும் சீராக்கவும்', 'Child settles jacket over both shoulders.', 'ஜாக்கெட்டை இரு தோள்களிலும் சீராகப் பொருத்தவும்.', 'Settle the jacket on your shoulders!', 'ஜாக்கெட்டை தோள்களில் நேராக வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (312, 3, 12, 'Straighten the jacket at the shoulders', 'தோள்பட்டையில் ஜாக்கெட்டை நேராக்கவும்', 'Child smooths fabric on shoulders.', 'தோள்பட்டைப் பகுதியில் உள்ள சுருக்கங்களை நீக்கவும்.', 'Smooth out the shoulders!', 'தோள்பட்டையை சரிசெய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (313, 3, 13, 'Bring both front sides of the jacket together', 'முன்பக்க இரு விளிம்புகளையும் ஒன்றாகக் கொண்டு வரவும்', 'Child aligns left and right zipper tracks.', 'இடது மற்றும் வலது ஜிப் பகுதிகளை ஒன்றாக இணைக்கவும்.', 'Bring the two front sides together!', 'இரு பக்கங்களையும் பக்கத்தில் கொண்டு வா!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (314, 3, 14, 'Find the zipper slider', 'ஜிப் ஸ்லைடரைக் கண்டறியவும்', 'Child locates the movable zipper slider.', 'நகரும் ஜிப் ஸ்லைடரைக் கண்டறியவும்.', 'Find the zipper slider at the bottom!', 'கீழே உள்ள ஜிப் ஸ்லைடரைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (315, 3, 15, 'Find the zipper insertion pin', 'ஜிப் ஊசியைக் கண்டறியவும்', 'Child finds insertion pin on opposite track.', 'மறுபுறம் உள்ள ஜிப் முனைக் கம்பியைக் கண்டறியவும்.', 'Find the pin on the other side!', 'மறுபக்கக் கம்பியைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (316, 3, 16, 'Hold the zipper slider with one hand', 'ஒரு கையால் ஜிப் ஸ்லைடரைப் பிடிக்கவும்', 'Child holds slider steady at bottom.', 'ஒரு கையால் ஸ்லைடரை கீழே கெட்டியாகப் பிடிக்கவும்.', 'Hold the zipper slider steady!', 'ஸ்லைடரை கெட்டியாகப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (317, 3, 17, 'Hold the insertion pin with the other hand', 'மற்றொரு கையால் ஊசியைப் பிடிக்கவும்', 'Child grasps insertion pin with other hand.', 'மற்றொரு கையால் கம்பியைப் பிடிக்கவும்.', 'Hold the insertion pin!', 'கம்பியைப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (318, 3, 18, 'Insert the pin fully into the zipper slider', 'ஊசியை ஸ்லைடருக்குள் முழுமையாக நுழைக்கவும்', 'Child pushes pin completely into base of slider.', 'கம்பியை ஸ்லைடருக்குள் கீழே வரை அழுத்தமாக நுழைக்கவும்.', 'Click the pin all the way into the slider!', 'கம்பியை உள்ளே அழுத்தி நுழை! கிளிக்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (319, 3, 19, 'Hold the bottom of the jacket steady', 'ஜாக்கெட்டின் கீழ் பகுதியை அசையாமல் பிடிக்கவும்', 'Child anchors bottom edge of jacket.', 'ஜாக்கெட்டின் கீழ் விளிம்பை அசையாமல் பிடிக்கவும்.', 'Hold the bottom of the jacket tight!', 'கீழ் பகுதியை கெட்டியாகப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (320, 3, 20, 'Pull the zipper slider upward', 'ஜிப் ஸ்லைடரை மேல்நோக்கி இழுக்கவும்', 'Child begins pulling slider up track.', 'ஸ்லைடரை மெதுவாக மேலே இழுக்கவும்.', 'Zip it up! Pull up!', 'ஜிப்பை மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (321, 3, 21, 'Continue pulling the zipper toward the chest', 'ஜிப்பை மார்பு வரை தொடர்ந்து இழுக்கவும்', 'Child pulls slider up past abdomen to chest.', 'ஜிப்பை மார்பு பகுதி வரை மேலே இழுத்துச் செல்லவும்.', 'Keep pulling up to your chest!', 'மார்பு வரை மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (322, 3, 22, 'Pull the zipper toward the neck', 'ஜிப்பை கழுத்து வரை இழுக்கவும்', 'Child pulls slider toward collar.', 'ஜிப்பை கழுத்து வரை மேலே கொண்டு வரவும்.', 'Pull up toward your neck!', 'கழுத்து வரை மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (323, 3, 23, 'Stop when the jacket is comfortably closed', 'வசதியாக மூடியவுடன் நிறுத்தவும்', 'Child ceases pulling at comfortable height.', 'போதுமான அளவு மூடியவுடன் ஜிப்பை இழுப்பதை நிறுத்தவும்.', 'Stop when it feels cozy!', 'போதுமானதும் நிறுத்து!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (324, 3, 24, 'Release the zipper', 'ஜிப்பை விடுவிக்கவும்', 'Child lets go of zipper pull.', 'ஜிப் பிடியை கையில் இருந்து விடவும்.', 'Let go of the zipper!', 'ஜிப்பை விட்டுவிடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (325, 3, 25, 'Straighten the jacket around the shoulders and waist', 'தோள்பட்டை மற்றும் இடுப்பில் நேராக்கவும்', 'Child smooths jacket front and waist.', 'ஜாக்கெட்டின் சுருக்கங்களை சரிசெய்து நேராக்கவும்.', 'Straighten your jacket nicely!', 'ஜாக்கெட்டை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (326, 3, 26, 'Check that the jacket is properly positioned and comfortable', 'ஜாக்கெட் சரியாகவும் வசதியாகவும் உள்ளதா எனப் பார்க்கவும்', 'Child confirms warmth and proper fit.', 'ஜாக்கெட் வசதியாகப் பொருத்தப்பட்டுள்ளதா என உறுதிசெய்யவும்.', 'Zipped up and ready! Great job!', 'ஜாக்கெட் போட்டாச்சு! சபாஷ்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (401, 4, 1, 'Move to a private changing area', 'தனிப்பட்ட உடை மாற்றும் அறைக்குச் செல்லவும்', 'Guide child to private space for dressing dignity.', 'குழந்தையை தனிப்பட்ட உடை மாற்றும் இடத்திற்கு அழைத்துச் செல்லவும்.', 'Let us step into your dressing area!', 'உடை மாற்றும் அறைக்கு வா!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (402, 4, 2, 'Pick up the vest', 'பனியனை எடுக்கவும்', 'Child picks up the clean vest.', 'சுத்தமான பனியனை கைகளில் எடுக்கவும்.', 'Pick up your vest!', 'பனியனை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (403, 4, 3, 'Identify the front and back', 'முன்புறம் மற்றும் பின்புறத்தை அறியவும்', 'Child distinguishes front lower scoop from back collar.', 'பின்பக்க லேபிளை அடையாளம் கண்டு முன்புறத்தை அறியவும்.', 'Find the tag on the back!', 'பின்பக்க லேபிளைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (404, 4, 4, 'Identify the neck opening', 'கழுத்துத் துவாரத்தை அறியவும்', 'Child finds center neck hole.', 'நடுவில் உள்ள பெரிய கழுத்துத் துவாரத்தைக் கண்டறியவும்.', 'Find the neck hole!', 'கழுத்துத் துவாரத்தைப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (405, 4, 5, 'Identify the right and left arm openings', 'இரு கை துவாரங்களையும் அறியவும்', 'Child locates both sleeveless arm openings.', 'இரு பக்கமும் உள்ள கைத் துவாரங்களை அடையாளம் காணவும்.', 'Find both arm holes!', 'இரு கை துவாரங்களையும் தொடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (406, 4, 6, 'Hold the vest near the shoulder areas', 'தோள்பட்டைப் பகுதிகளைப் பிடிக்கவும்', 'Child grasps vest by upper straps.', 'பனியனின் மேல் பட்டைகளைப் பிடிக்கவும்.', 'Hold the vest at the shoulders!', 'தோள்பட்டையில் பனியனைப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (407, 4, 7, 'Lift the vest to chest level', 'பனியனை மார்பு உயரத்திற்கு உயர்த்தவும்', 'Child raises vest upward.', 'பனியனை மார்பு உயரத்திற்கு தூக்கவும்.', 'Lift the vest up to your chest!', 'மார்பு உயரத்திற்கு தூக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (408, 4, 8, 'Put the head through the neck opening', 'தலையை துவாரத்திற்குள் நுழைக்கவும்', 'Child ducks head through neck opening.', 'தலையை கழுத்துத் துவாரத்திற்குள் நுழைக்கவும்.', 'Pop your head through the hole!', 'தலையை உள்ளே நுழை! பீக்கபூ!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (409, 4, 9, 'Pull the vest down over the head', 'தலையைக் கடந்து பனியனை கீழே இழுக்கவும்', 'Child brings vest down onto neck.', 'பனியனை கழுத்து வரை கீழே இறக்கவும்.', 'Pull the vest down over your head!', 'தலையைக் கடந்து கீழே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (410, 4, 10, 'Find the right arm opening', 'வலது கைத் துவாரத்தைக் கண்டறியவும்', 'Child locates right strap armhole.', 'வலது கைத் துவாரத்தைக் கண்டறியவும்.', 'Find the right arm hole!', 'வலது துவாரத்தைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (411, 4, 11, 'Put the right arm through the opening', 'வலது கையை துவாரத்தில் நுழைக்கவும்', 'Child passes right arm through.', 'வலது கையை துவாரத்தின் வழியே வெளியே கொண்டு வரவும்.', 'Push your right arm through!', 'வலது கையை உள்ளே நுழை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
