INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (416, 4, 16, 'Pull the vest down over the chest', 'பனியனை மார்பின் மேல் கீழே இழுக்கவும்', 'Child smooths vest over chest.', 'பனியனை மார்புப் பகுதியில் கீழ்நோக்கி இழுக்கவும்.', 'Pull the vest down over your chest!', 'மார்பின் மேல் கீழே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (417, 4, 17, 'Pull the vest down over the abdomen', 'பனியனை வயிற்றின் மேல் கீழே இழுக்கவும்', 'Child pulls lower edge past belly.', 'பனியனின் கீழ் விளிம்பை தொப்புளுக்குக் கீழே இழுக்கவும்.', 'Pull it all the way down over your tummy!', 'வயிற்றுக்கு கீழே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (418, 4, 18, 'Straighten the vest around the shoulders', 'தோள்பட்டையில் பனியனை நேராக்கவும்', 'Child checks both straps are flat.', 'இரு தோள்பட்டைப் பட்டைகளும் தட்டையாக உள்ளதா எனப் பார்க்கவும்.', 'Fix the straps on your shoulders!', 'பட்டைகளை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (419, 4, 19, 'Straighten the lower edge around the waist', 'இடுப்புப் பகுதியில் கீழ் விளிம்பை நேராக்கவும்', 'Child straightens bottom hem.', 'கீழ் விளிம்பை இடுப்பில் சுருக்கமின்றி சரிசெய்யவும்.', 'Straighten the bottom around your waist!', 'கீழ் விளிம்பை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (420, 4, 20, 'Check that the vest is correctly positioned and comfortable', 'பனியன் வசதியாக உள்ளதா என சரிபார்க்கவும்', 'Child confirms undergarment comfort.', 'பனியன் வசதியாகப் பொருந்தியுள்ளதை உறுதிசெய்யவும்.', 'All done! You are comfy in your vest!', 'அருமை! பனியன் வசதியாக உள்ளது!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (501, 5, 1, 'Stand in front of the trousers', 'கால்சட்டையின் முன் நிற்கவும்', 'Child stands facing open trousers.', 'கால்சட்டைக்கு முன் நேராக நிற்கவும்.', 'Stand in front of your trousers!', 'கால்சட்டை முன் நில்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (502, 5, 2, 'Look at the trousers', 'கால்சட்டையைப் பார்க்கவும்', 'Child visually examines waistband and legs.', 'இடுப்புப் பட்டை மற்றும் கால் பகுதிகளைப் பார்க்கவும்.', 'Look at your trousers!', 'கால்சட்டையைப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (503, 5, 3, 'Pick up the trousers using both hands', 'இரு கைகளாலும் கால்சட்டையை எடுக்கவும்', 'Child lifts trousers securely.', 'இரு கைகளாலும் கால்சட்டையை மேலே எடுக்கவும்.', 'Pick up your trousers with both hands!', 'இரு கைகளாலும் கால்சட்டையை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (504, 5, 4, 'Identify the front and back', 'முன்புறம் மற்றும் பின்புறத்தை அறியவும்', 'Child locates drawstrings in front.', 'முன்புற நாடாவையும் பின்பக்கத்தையும் அடையாளம் காணவும்.', 'Find the drawstrings in the front!', 'முன்பக்க நாடாவைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (505, 5, 5, 'Find the waistband', 'இடுப்புப் பட்டையைக் கண்டறியவும்', 'Child finds top circular waistband.', 'மேல் இடுப்புப் பட்டையைத் தொடவும்.', 'Find the waistband at the top!', 'இடுப்புப் பட்டையைத் தொடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (506, 5, 6, 'Find the right leg opening', 'வலது கால் துவாரத்தைக் கண்டறியவும்', 'Child locates right pant leg.', 'வலது கால் குழாயைக் கண்டறியவும்.', 'Find the right leg hole!', 'வலது கால் துவாரத்தைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (507, 5, 7, 'Find the left leg opening', 'இடது கால் துவாரத்தைக் கண்டறியவும்', 'Child locates left pant leg.', 'இடது கால் குழாயைக் கண்டறியவும்.', 'Find the left leg hole!', 'இடது கால் துவாரத்தைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (508, 5, 8, 'Hold the waistband with both hands', 'இரு கைகளாலும் இடுப்புப் பட்டையைப் பிடிக்கவும்', 'Child grips left and right waistband.', 'இடுப்புப் பட்டையை இரு கைகளாலும் பிடிக்கவும்.', 'Hold the waistband open with both hands!', 'இடுப்புப் பட்டையை இரு கைகளாலும் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (509, 5, 9, 'Step one foot into the correct leg opening', 'ஒரு காலை சரியான கால் துவாரத்தில் வைக்கவும்', 'Child steps foot into opening.', 'ஒரு பாதத்தை கால் துவாரத்திற்குள் வைக்கவும்.', 'Step your foot into the leg hole!', 'ஒரு காலை உள்ளே வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (510, 5, 10, 'Push the foot through the leg opening', 'பாதத்தை துவாரம் வழியே வெளியே தள்ளவும்', 'Child extends foot all the way through bottom hem.', 'பாதத்தை கீழ் துவாரம் வழியே வெளியே கொண்டு வரவும்.', 'Push your foot all the way through!', 'பாதத்தை வெளியே தள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (511, 5, 11, 'Step the other foot into the other leg opening', 'மற்றொரு காலை அடுத்த துவாரத்தில் வைக்கவும்', 'Child lifts second foot into opening.', 'அடுத்த பாதத்தை மற்ற கால் துவாரத்தில் வைக்கவும்.', 'Step your other foot into the other hole!', 'அடுத்த காலை உள்ளே வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (512, 5, 12, 'Push the second foot through the leg opening', 'இரண்டாவது பாதத்தையும் வெளியே தள்ளவும்', 'Child extends second foot through cuff.', 'இரண்டாவது பாதத்தையும் கீழே வெளியே கொண்டு வரவும்.', 'Push your other foot all the way through!', 'மறு பாதத்தையும் வெளியே தள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (513, 5, 13, 'Pull the trousers upward from the thighs', 'தொடை வரை கால்சட்டையை மேலே இழுக்கவும்', 'Child gathers fabric and pulls up to knees/thighs.', 'கால்சட்டையை முழங்கால் மற்றும் தொடை வரை மேலே இழுக்கவும்.', 'Pull your trousers up to your thighs!', 'தொடை வரை மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (514, 5, 14, 'Stand upright safely', 'பாதுகாப்பாக நேராக நிற்கவும்', 'Child establishes balance.', 'சமநிலையுடன் நேராக நிற்கவும்.', 'Stand up tall and balanced!', 'நேராக நில்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (515, 5, 15, 'Pull the waistband up toward the waist', 'இடுப்புப் பட்டையை இடுப்பு வரை இழுக்கவும்', 'Child raises waistband over hips.', 'இடுப்புப் பட்டையை இடுப்பு வரை மேலே இழுக்கவும்.', 'Pull the waistband up to your waist!', 'இடுப்பு வரை இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (516, 5, 16, 'Check that the waistband is positioned evenly', 'இடுப்புப் பட்டை சீராக உள்ளதா என சரிபார்க்கவும்', 'Child aligns waistband level around hips.', 'இடுப்புப் பட்டை சரிசமமாக உள்ளதா எனப் பார்க்கவும்.', 'Make sure the waistband is even!', 'இடுப்புப் பட்டையை சமமாக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (517, 5, 17, 'Find the two ends of the drawstring', 'நாடாவின் இரு முனைகளையும் கண்டறியவும்', 'Child locates both drawstring cords.', 'நாடாவின் இரு முனைகளையும் கைகளில் எடுக்கவும்.', 'Find both ends of the string!', 'இரு நாடா முனைகளையும் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (518, 5, 18, 'Hold one end of the drawstring in each hand', 'ஒவ்வொரு கையிலும் ஒரு முனையைப் பிடிக்கவும்', 'Child grips left and right strings.', 'ஒவ்வொரு கையிலும் ஒரு நாடாவைப் பிடிக்கவும்.', 'Hold one string in each hand!', 'இரு கைகளிலும் நாடாவைப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (519, 5, 19, 'Pull both ends to tighten the waistband', 'இடுப்புப் பட்டையை இறுக்க நாடாக்களை இழுக்கவும்', 'Child pulls cords laterally to snug fit.', 'இடுப்புக்கு தகுந்தவாறு இரு நாடாக்களையும் இழுக்கவும்.', 'Pull both strings to make it snug!', 'நாடாக்களை இழுத்து இறுக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (520, 5, 20, 'Cross one drawstring over the other', 'ஒரு நாடாவை மற்றொன்றின் மேல் குறுக்காக வைக்கவும்', 'Child crosses cords forming an X.', 'ஒரு நாடாவை மற்றொன்றின் மீது குறுக்காக வைக்கவும்.', 'Cross one string over the other!', 'நாடாக்களை குறுக்காக வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (521, 5, 21, 'Make a loop with one end', 'ஒரு முனையில் சுருக்கு வளையம் செய்யவும்', 'Child folds one cord into loop.', 'ஒரு நாடாவில் சிறிய வளையம் உருவாக்கவும்.', 'Make a loop like a bunny ear!', 'ஒரு முயல் காது போல வளையம் செய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (522, 5, 22, 'Wrap the other end around the loop', 'மற்றொரு நாடாவை வளையத்தைச் சுற்றி சுற்றவும்', 'Child wraps second cord around base of loop.', 'மற்றொரு நாடாவை அந்த வளையத்தைச் சுற்றி சுற்றவும்.', 'Wrap the other string around the loop!', 'சுற்றி வளைத்து எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (523, 5, 23, 'Push the end through to form a knot/bow', 'முனையை துளை வழியே தள்ளி முடிச்சு போடவும்', 'Child pushes loop through center hole.', 'நாடாவை நடுவில் தள்ளி முடிச்சு உருவாக்கவும்.', 'Push it through to make the bow!', 'உள்ளே தள்ளி முடிச்சு போடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (524, 5, 24, 'Pull both loops/ends to secure the knot', 'முடிச்சை இறுக்க இரு வளையங்களையும் இழுக்கவும்', 'Child tightens bow firmly.', 'முடிச்சை உறுதியாக இழுத்து இறுக்கவும்.', 'Pull both loops tight!', 'இரு பக்கமும் இழுத்து கெட்டியாக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (525, 5, 25, 'Check that the trousers are secure', 'கால்சட்டை நழுவாமல் உள்ளதா என சரிபார்க்கவும்', 'Child tests snugness around waist.', 'கால்சட்டை நழுவாமல் சரியாக உள்ளதா என உறுதிசெய்யவும்.', 'Make sure your trousers stay up!', 'சரியாக உள்ளதா எனப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (526, 5, 26, 'Straighten the trousers around the waist and legs', 'இடுப்பு மற்றும் கால்களில் நேராக்கவும்', 'Child smooths fabric down legs.', 'கால்சட்டையில் உள்ள சுருக்கங்களை நேராக்கவும்.', 'Smooth down the legs and waist!', 'கால்சட்டையை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (527, 5, 27, 'Check that both feet and legs are comfortable', 'கால்கள் இரண்டும் வசதியாக உள்ளதா என சரிபார்க்கவும்', 'Child confirms full comfort and mobility.', 'நடந்து பார்த்து வசதியை உறுதிசெய்யவும்.', 'All tied! Walk around, you look fantastic!', 'முடிச்சு போட்டாச்சு! சூப்பர்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (601, 6, 1, 'Stand in front of the jeans', 'ஜீன்ஸின் முன் நிற்கவும்', 'Child faces jeans placed flat.', 'ஜீன்ஸுக்கு முன் நேராக நிற்கவும்.', 'Stand in front of your jeans!', 'ஜீன்ஸ் முன் நில்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (602, 6, 2, 'Look at the jeans', 'ஜீன்ஸைப் பார்க்கவும்', 'Child observes waist and legs.', 'ஜீன்ஸின் அமைப்பைப் பார்க்கவும்.', 'Look at the jeans!', 'ஜீன்ஸைப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (603, 6, 3, 'Pick up the jeans using both hands', 'இரு கைகளாலும் ஜீன்ஸை எடுக்கவும்', 'Child lifts jeans by waistband.', 'இரு கைகளாலும் ஜீன்ஸை எடுக்கவும்.', 'Pick up your jeans!', 'ஜீன்ஸை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (604, 6, 4, 'Identify the front and back', 'முன்புறம் மற்றும் பின்புறத்தை அறியவும்', 'Child identifies front zipper/button vs back pockets.', 'முன்பக்க ஜிப் மற்றும் பின்பக்க பைகளை அடையாளம் காணவும்.', 'Find the button in the front and pockets in the back!', 'முன்பக்க பொத்தானைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (605, 6, 5, 'Find the waistband', 'இடுப்புப் பட்டையைக் கண்டறியவும்', 'Child locates top waistband.', 'இடுப்புப் பட்டையைத் தொடவும்.', 'Find the waistband!', 'இடுப்புப் பட்டையைத் தொடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (606, 6, 6, 'Find the right leg opening', 'வலது கால் துவாரத்தைக் கண்டறியவும்', 'Child finds right leg opening.', 'வலது கால் குழாயைக் கண்டறியவும்.', 'Find the right leg hole!', 'வலது கால் துவாரத்தைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (607, 6, 7, 'Find the left leg opening', 'இடது கால் துவாரத்தைக் கண்டறியவும்', 'Child finds left leg opening.', 'இடது கால் குழாயைக் கண்டறியவும்.', 'Find the left leg hole!', 'இடது கால் துவாரத்தைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
