INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (622, 6, 22, 'Hold the waistband near the button', 'பொத்தானுக்கு அருகில் இடுப்புப் பட்டையைப் பிடிக்கவும்', 'Child braces buttonhole fabric.', 'துளை உள்ள பகுதியை ஒரு கையால் பிடிக்கவும்.', 'Hold the waistband near the button!', 'இடுப்புப் பட்டையை கெட்டியாகப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
