INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (625, 6, 25, 'Check that the zipper and button are secured', 'ஜிப் மற்றும் பொத்தான் பூட்டப்பட்டுள்ளதை சரிபார்க்கவும்', 'Child verifies button and zipper closure.', 'இரண்டும் சரியாக மூடப்பட்டுள்ளதா எனப் பார்க்கவும்.', 'Check your button and zipper!', 'பொத்தானும் ஜிப்பும் சரியா எனப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
