INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1605, 16, 5, 'Identify the right and left leg openings', 'இரு கால் துவாரங்களையும் அறியவும்', 'Child locates both leg openings.', 'இரு கால் துவாரங்களையும் அடையாளம் காணவும்.', 'Find both leg holes!', 'இரு துவாரங்களையும் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1606, 16, 6, 'Hold the waistband with both hands', 'இரு கைகளாலும் இடுப்புப் பட்டையைப் பிடிக்கவும்', 'Child grasps sides of waistband.', 'இடுப்புப் பட்டையை இரு கைகளாலும் பிடிக்கவும்.', 'Hold the waistband with both hands!', 'இரு கைகளாலும் பட்டையைப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1607, 16, 7, 'Open the waistband', 'இடுப்புப் பட்டையை விரிக்கவும்', 'Child stretches opening wide.', 'இடுப்புப் பட்டையை விரிக்கவும்.', 'Stretch the waistband open wide!', 'பட்டையை அகலமாக விரி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1608, 16, 8, 'Step one foot into the corresponding leg opening', 'ஒரு காலை துவாரத்தில் வைக்கவும்', 'Child steps foot in.', 'ஒரு பாதத்தை உள்ளே வைக்கவும்.', 'Step one foot into the leg hole!', 'ஒரு காலை உள்ளே வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1609, 16, 9, 'Push the foot through the opening', 'பாதத்தை துவாரம் வழியே வெளியே தள்ளவும்', 'Child extends foot completely through.', 'பாதத்தை வெளியே தள்ளவும்.', 'Push your foot all the way through!', 'பாதத்தை வெளியே தள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1610, 16, 10, 'Step the other foot into the other leg opening', 'மற்றொரு காலை அடுத்த துவாரத்தில் வைக்கவும்', 'Child steps second foot in.', 'அடுத்த பாதத்தை மற்ற துவாரத்தில் வைக்கவும்.', 'Step your other foot in!', 'அடுத்த காலை உள்ளே வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1611, 16, 11, 'Push the second foot through', 'இரண்டாவது பாதத்தையும் வெளியே தள்ளவும்', 'Child pushes foot through.', 'இரண்டாவது பாதத்தை வெளியே தள்ளவும்.', 'Push your other foot all the way through!', 'மறு பாதத்தையும் வெளியே தள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1612, 16, 12, 'Pull the underwear upward to the knees', 'முழங்கால் வரை மேலே இழுக்கவும்', 'Child pulls briefs to knees.', 'உள்ளாடையை முழங்கால் வரை இழுக்கவும்.', 'Pull up to your knees!', 'முழங்கால் வரை இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1613, 16, 13, 'Pull the underwear upward toward the thighs', 'தொடை வரை மேலே இழுக்கவும்', 'Child pulls briefs onto thighs.', 'உள்ளாடையை தொடை வரை இழுக்கவும்.', 'Pull up to your thighs!', 'தொடை வரை இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1614, 16, 14, 'Pull the waistband upward toward the waist', 'இடுப்பு வரை மேலே இழுக்கவும்', 'Child pulls waistband over hips to waist.', 'இடுப்புப் பட்டையை இடுப்பு வரை மேலே இழுக்கவும்.', 'Pull the waistband up to your waist!', 'இடுப்பு வரை மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1615, 16, 15, 'Adjust the front and back', 'முன்புறம் மற்றும் பின்புறத்தை சரிசெய்யவும்', 'Child ensures coverage is balanced.', 'முன்புறமும் பின்புறமும் சீராக உள்ளதா என சரிசெய்யவும்.', 'Adjust the front and back evenly!', 'முன்பக்கமும் பின்பக்கமும் சரிசெய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1616, 16, 16, 'Check that both legs are correctly positioned', 'இரு கால்களும் சரியாக உள்ளதா எனப் பார்க்கவும்', 'Child checks leg openings fit comfortably.', 'கால் துவாரங்கள் வசதியாக உள்ளதா எனப் பார்க்கவும்.', 'Make sure both legs feel comfy!', 'இரு கால்களையும் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1617, 16, 17, 'Straighten the waistband', 'இடுப்புப் பட்டையை நேராக்கவும்', 'Child flattens elastic waistband.', 'இடுப்புப் பட்டையை சுருக்கமின்றி நேராக்கவும்.', 'Straighten your waistband flat!', 'இடுப்புப் பட்டையை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1618, 16, 18, 'Smooth the underwear around the hips and thighs', 'இடுப்பு மற்றும் தொடைகளில் நேராக்கவும்', 'Child smooths fabric.', 'சுருக்கங்களை கை வைத்து நீக்கவும்.', 'Smooth down the sides!', 'பக்கவாட்டில் நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1619, 16, 19, 'Check that the underwear is comfortable and secure', 'உள்ளாடை வசதியாகவும் சரியாகவும் உள்ளதா என உறுதிசெய்யவும்', 'Child confirms comfort.', 'உள்ளாடை வசதியாக உள்ளதை உறுதிசெய்யவும்.', 'Comfortable and snug! Great job!', 'உள்ளாடை வசதியாக உள்ளது! சபாஷ்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1620, 16, 20, 'Put the outer clothing over the undergarment', 'உள்ளாடையின் மேல் வெளிப்புற உடையை அணியவும்', 'Child is ready for pants or shorts.', 'இப்போது கால்சட்டை அணியத் தயாராகலாம்.', 'Now you are ready for your shorts or trousers!', 'இப்போது கால்சட்டை போடலாம்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1701, 17, 1, 'Look at the T-shirt', 'டி-சர்ட்டைப் பார்க்கவும்', 'Child focuses attention on the T-shirt placed flat.', 'குழந்தையை தட்டையாக வைக்கப்பட்டுள்ள டி-சர்ட்டைப் பார்க்கச் சொல்லவும்.', 'Look at your pretty T-shirt!', 'உன் அழகான டி-சர்ட்டைப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1702, 17, 2, 'Pick up the T-shirt using both hands', 'இரு கைகளாலும் டி-சர்ட்டை எடுக்கவும்', 'Child picks up the T-shirt using both hands.', 'இரு கைகளாலும் டி-சர்ட்டை எடுக்கவும்.', 'Pick up your T-shirt with two hands!', 'இரு கைகளாலும் டி-சர்ட்டை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1703, 17, 3, 'Identify the front and back of the T-shirt', 'முன்புறம் மற்றும் பின்புறத்தை அடையாளம் காணவும்', 'Child identifies front design or back tag.', 'முன்பக்க வடிவமைப்பு அல்லது பின்பக்க லேபிளை அடையாளம் காணவும்.', 'Find the front picture and back tag!', 'முன்பக்க படத்தைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1704, 17, 4, 'Identify the neck opening', 'கழுத்துத் துவாரத்தை அடையாளம் காணவும்', 'Child locates the neck opening.', 'கழுத்துத் துவாரத்தைத் தொட்டுப் பார்க்கவும்.', 'Find the neck hole!', 'கழுத்துத் துவாரத்தைத் தொடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1705, 17, 5, 'Hold the T-shirt near the shoulder areas', 'தோள்பட்டைப் பகுதிகளைப் பிடிக்கவும்', 'Child grips T-shirt near shoulder seams.', 'தோள்பட்டைப் பகுதிகளை இரு கைகளாலும் பிடிக்கவும்.', 'Hold the T-shirt at the shoulders!', 'தோள்பட்டையில் டி-சர்ட்டைப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1706, 17, 6, 'Lift the T-shirt to chest level', 'டி-சர்ட்டை மார்பு உயரத்திற்கு உயர்த்தவும்', 'Child lifts T-shirt to chest level.', 'டி-சர்ட்டை மார்பு உயரத்திற்கு தூக்கவும்.', 'Lift the T-shirt up high to your chest!', 'மார்பு உயரத்திற்கு தூக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1707, 17, 7, 'Put the head through the neck opening', 'தலையை கழுத்துத் துவாரத்தில் நுழைக்கவும்', 'Child guides head through collar opening.', 'தலையை கழுத்துத் துவாரத்திற்குள் நுழைக்கவும்.', 'Pop your head through the neck hole! Peekaboo!', 'தலையை உள்ளே நுழை! எட்டிப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1708, 17, 8, 'Pull the T-shirt down over the head', 'தலையைக் கடந்து கீழே இழுக்கவும்', 'Child pulls collar down onto neck.', 'டி-சர்ட்டை கழுத்து வரை கீழே இழுக்கவும்.', 'Pull the shirt down over your head!', 'தலையைக் கடந்து கீழே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1709, 17, 9, 'Find the right sleeve opening', 'வலது கை துவாரத்தைக் கண்டறியவும்', 'Child locates right sleeve.', 'வலது கைத் துவாரத்தைக் கண்டறியவும்.', 'Find the right sleeve hole!', 'வலது கைத் துவாரத்தைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1710, 17, 10, 'Put the right arm through the right sleeve', 'வலது கையை வலது குழாயில் நுழைக்கவும்', 'Child pushes right hand and arm through.', 'வலது கையை குழாயில் நுழைத்து வெளியே கொண்டு வரவும்.', 'Push your right arm through the sleeve!', 'வலது கையை உள்ளே நுழை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1711, 17, 11, 'Pull the right sleeve toward the shoulder', 'வலது கையை தோள்பட்டை வரை இழுக்கவும்', 'Child pulls right sleeve up.', 'வலது கை சட்டையை தோள்பட்டை வரை மேலே இழுக்கவும்.', 'Pull the sleeve up on your right shoulder!', 'தோள்பட்டை வரை இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1712, 17, 12, 'Find the left sleeve opening', 'இடது கை துவாரத்தைக் கண்டறியவும்', 'Child locates left sleeve.', 'இடது கைத் துவாரத்தைக் கண்டறியவும்.', 'Find the left sleeve hole!', 'இடது கைத் துவாரத்தைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1713, 17, 13, 'Put the left arm through the left sleeve', 'இடது கையை இடது குழாயில் நுழைக்கவும்', 'Child pushes left hand and arm through.', 'இடது கையை குழாயில் நுழைத்து வெளியே கொண்டு வரவும்.', 'Push your left arm through the sleeve!', 'இடது கையை உள்ளே நுழை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1714, 17, 14, 'Pull the left sleeve toward the shoulder', 'இடது கையை தோள்பட்டை வரை இழுக்கவும்', 'Child pulls left sleeve up.', 'இடது கை சட்டையை தோள்பட்டை வரை மேலே இழுக்கவும்.', 'Pull the sleeve up on your left shoulder!', 'தோள்பட்டை வரை இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1715, 17, 15, 'Pull the front of the T-shirt down', 'முன்பகுதியை கீழே இழுக்கவும்', 'Child pulls front hem down over torso.', 'முன்பக்க விளிம்பைப் பிடித்து கீழ்நோக்கி இழுக்கவும்.', 'Pull the front of your shirt down!', 'முன்பக்கத்தை கீழே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1716, 17, 16, 'Pull the back of the T-shirt down', 'பின்பகுதியை கீழே இழுக்கவும்', 'Child reaches back and pulls hem down.', 'பின்பக்க விளிம்பைப் பிடித்து கீழே இழுத்து விடவும்.', 'Pull the back of your shirt down smooth!', 'பின்பக்கத்தை கீழே இழுத்து விடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1717, 17, 17, 'Straighten the T-shirt around the shoulders', 'தோள்பட்டையில் நேராக்கவும்', 'Child smooths fabric on shoulders.', 'தோள்பட்டைப் பகுதியில் உள்ள சுருக்கங்களை சரிசெய்யவும்.', 'Fix your shirt at the shoulders!', 'தோள்பட்டையை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1718, 17, 18, 'Straighten the T-shirt around the waist', 'இடுப்பில் நேராக்கவும்', 'Child adjusts lower hem around waist.', 'இடுப்புப் பகுதியில் சட்டையை சுருக்கமின்றி சரிசெய்யவும்.', 'Straighten your shirt at the waist!', 'இடுப்பில் நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1719, 17, 19, 'Check that the T-shirt is correctly positioned and comfortable', 'டி-சர்ட் வசதியாகவும் சரியாகவும் உள்ளதா எனப் பார்க்கவும்', 'Child inspects fit.', 'டி-சர்ட் வசதியாக உள்ளதா என சரிபார்த்து மகிழவும்.', 'Look in the mirror! You look wonderful!', 'கண்ணாடியில் பார்! மிக அழகாக உள்ளது!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1801, 18, 1, 'Stand or sit in front of the top', 'மேலாடையின் முன் நிற்கவும் அல்லது அமரவும்', 'Child faces top placed flat.', 'மேலாடைக்கு முன் நேராக நிற்கவும் அல்லது அமரவும்.', 'Stand or sit in front of your top!', 'மேலாடையின் முன் அமர்ந்து கொள்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1802, 18, 2, 'Look at the top', 'மேலாடையைப் பார்க்கவும்', 'Child observes open top and buttons.', 'திறந்துள்ள மேலாடையைப் பார்க்கவும்.', 'Look at the top!', 'மேலாடையைப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1803, 18, 3, 'Pick up the top using both hands', 'இரு கைகளாலும் மேலாடையை எடுக்கவும்', 'Child lifts top.', 'இரு கைகளாலும் மேலாடையை எடுக்கவும்.', 'Pick up your top with two hands!', 'இரு கைகளாலும் மேலாடையை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1804, 18, 4, 'Identify the front and back', 'முன்புறம் மற்றும் பின்புறத்தை அறியவும்', 'Child finds buttons on front.', 'முன்பக்க பொத்தான்களை அடையாளம் காணவும்.', 'Find the front with buttons!', 'பொத்தான்கள் உள்ள முன்பக்கத்தைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1805, 18, 5, 'Identify the collar/neck opening', 'காலர் பகுதியை அடையாளம் காணவும்', 'Child locates collar.', 'காலர் பகுதியைத் தொடவும்.', 'Find the collar at the top!', 'மேலே உள்ள காலரைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1806, 18, 6, 'Identify the right sleeve', 'வலது கைக்குழாயை அறியவும்', 'Child locates right sleeve.', 'வலது கைக்குழாயைக் கண்டறியவும்.', 'Find the right sleeve!', 'வலது கைக் குழாயைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1807, 18, 7, 'Identify the left sleeve', 'இடது கைக்குழாயை அறியவும்', 'Child locates left sleeve.', 'இடது கைக்குழாயைக் கண்டறியவும்.', 'Find the left sleeve!', 'இடது கைக் குழாயைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1808, 18, 8, 'Put the right arm into the right sleeve', 'வலது கையை வலது குழாயில் நுழைக்கவும்', 'Child inserts right arm into sleeve.', 'வலது கையை குழாயில் நுழைக்கவும்.', 'Slide your right arm in!', 'வலது கையை உள்ளே நுழை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1809, 18, 9, 'Pull the right sleeve toward the shoulder', 'வலது குழாயை தோள்பட்டை வரை இழுக்கவும்', 'Child pulls right sleeve up.', 'வலது கையை தோள்பட்டை வரை மேலே இழுக்கவும்.', 'Pull the right sleeve up high!', 'தோள்பட்டை வரை இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1810, 18, 10, 'Put the left arm into the left sleeve', 'இடது கையை இடது குழாயில் நுழைக்கவும்', 'Child inserts left arm into sleeve.', 'இடது கையை குழாயில் நுழைக்கவும்.', 'Slide your left arm in!', 'இடது கையை உள்ளே நுழை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1811, 18, 11, 'Pull the left sleeve toward the shoulder', 'இடது குழாயை தோள்பட்டை வரை இழுக்கவும்', 'Child pulls left sleeve up.', 'இடது கையை தோள்பட்டை வரை மேலே இழுக்கவும்.', 'Pull the left sleeve up high!', 'தோள்பட்டை வரை இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1812, 18, 12, 'Pull the top onto both shoulders', 'மேலாடையை இரு தோள்களிலும் சீராக்கவும்', 'Child positions top across shoulders.', 'மேலாடையை இரு தோள்களிலும் சீராகப் பொருத்தவும்.', 'Settle the top on both shoulders!', 'தோள்களில் மேலாடையை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1813, 18, 13, 'Straighten the top around the shoulders', 'தோள்பட்டையில் நேராக்கவும்', 'Child smooths fabric on shoulders.', 'தோள்பட்டைப் பகுதியில் உள்ள சுருக்கங்களை நீக்கவும்.', 'Smooth out the shoulders!', 'தோள்பட்டையை சரிசெய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1814, 18, 14, 'Bring the two front panels together', 'முன்பக்க இரு விளிம்புகளையும் ஒன்றாகக் கொண்டு வரவும்', 'Child aligns button and buttonhole edges.', 'முன்பக்க இரு விளிம்புகளையும் ஒன்றாக இணைக்கவும்.', 'Bring the front sides together!', 'இரு பக்கங்களையும் இணை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1815, 18, 15, 'Locate the top button and corresponding buttonhole', 'முதல் பொத்தான் மற்றும் துளையைக் கண்டறியவும்', 'Child finds top button and hole.', 'முதல் பொத்தானையும் அதன் காஜாவையும் கண்டறியவும்.', 'Find the top button and hole!', 'முதல் பொத்தானையும் துளையையும் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1816, 18, 16, 'Hold the buttonhole with one hand', 'ஒரு கையால் பொத்தான் துளையைப் பிடிக்கவும்', 'Child holds buttonhole fabric.', 'ஒரு கையால் காஜா துணியை கெட்டியாகப் பிடிக்கவும்.', 'Hold the buttonhole steady!', 'துளையை கெட்டியாகப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1817, 18, 17, 'Hold the button with the other hand', 'மற்றொரு கையால் பொத்தானைப் பிடிக்கவும்', 'Child grasps button with pincer grip.', 'மற்றொரு கையால் பொத்தானை விரல்களால் பிடிக்கவும்.', 'Hold the button with your fingers!', 'பொத்தானைப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1818, 18, 18, 'Push the button through the buttonhole', 'பொத்தானை துளைக்குள் தள்ளவும்', 'Child pushes button through hole.', 'பொத்தானை துளைக்குள் தள்ளவும்.', 'Push the button halfway through!', 'பொத்தானை உள்ளே தள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1819, 18, 19, 'Pull the button completely through', 'பொத்தானை முழுமையாக வெளியே இழுக்கவும்', 'Child pulls button through to secure.', 'பொத்தானை மறுபுறம் இழுத்து மாட்டவும்.', 'Pull the button completely through!', 'வெளியே இழுத்து மாட்டிவிடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1820, 18, 20, 'Check that the button is secured', 'பொத்தான் மாட்டப்பட்டுள்ளதை சரிபார்க்கவும்', 'Child confirms button is fastened.', 'பொத்தான் சரியாக மாட்டப்பட்டுள்ளதா எனப் பார்க்கவும்.', 'Good! Button is fastened!', 'பொத்தான் மாட்டியாச்சு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1821, 18, 21, 'Repeat the same sequence for the next button', 'அடுத்த பொத்தானையும் அவ்வாறே மாட்டவும்', 'Child fastens second button.', 'அடுத்த பொத்தானையும் துளையோடு இணைத்து மாட்டவும்.', 'Now do the next button down!', 'அடுத்த பொத்தானையும் மாட்டு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1822, 18, 22, 'Continue buttoning from top to bottom', 'மேலிருந்து கீழ் நோக்கி தொடர்ந்து மாட்டவும்', 'Child fastens all buttons.', 'வரிசையாக அனைத்து பொத்தான்களையும் மாட்டவும்.', 'Button all the way down!', 'கீழ் வரை எல்லா பொத்தான்களையும் மாட்டு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1823, 18, 23, 'Pull the top down toward the waist', 'மேலாடையை இடுப்பு வரை கீழே இழுக்கவும்', 'Child pulls panels down.', 'மேலாடையின் கீழ் பகுதியை இடுப்பு வரை இழுத்து விடவும்.', 'Pull your top down to your waist!', 'கீழே இழுத்து விடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1824, 18, 24, 'Straighten the collar', 'காலரை நேராக்கவும்', 'Child adjusts collar neatly.', 'காலரை சுருக்கமின்றி நேராக்கவும்.', 'Fix your collar neat and tidy!', 'காலரை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1825, 18, 25, 'Straighten both sleeves', 'இரு கைகளையும் நேராக்கவும்', 'Child smooths sleeves.', 'இரு கைகளிலும் உள்ள சுருக்கங்களை நீக்கவும்.', 'Smooth down both sleeves!', 'கைகளை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1826, 18, 26, 'Check that all required buttons are fastened and the top is positioned comfortably', 'அனைத்து பொத்தான்களும் மாட்டப்பட்டு வசதியாக உள்ளதா எனப் பார்க்கவும்', 'Child confirms complete fit.', 'அனைத்து பொத்தான்களும் மாட்டப்பட்டு வசதியாக உள்ளதா என உறுதிசெய்யவும்.', 'All buttoned up and looking lovely!', 'அனைத்தும் சரியாக உள்ளது! மிக அழகு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1901, 19, 1, 'Stand or sit in front of the jacket', 'ஜாக்கெட்டின் முன் நிற்கவும் அல்லது அமரவும்', 'Child faces flat jacket.', 'ஜாக்கெட்டின் முன் நேராக நிற்கவும் அல்லது அமரவும்.', 'Stand or sit in front of your jacket!', 'ஜாக்கெட் முன் நில்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1902, 19, 2, 'Look at the jacket', 'ஜாக்கெட்டைப் பார்க்கவும்', 'Child looks at open jacket.', 'திறந்துள்ள ஜாக்கெட்டைப் பார்க்கவும்.', 'Look at the jacket!', 'ஜாக்கெட்டைப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1903, 19, 3, 'Pick up the jacket', 'ஜாக்கெட்டை எடுக்கவும்', 'Child picks up jacket.', 'இரு கைகளாலும் ஜாக்கெட்டை எடுக்கவும்.', 'Pick up your jacket!', 'ஜாக்கெட்டை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1904, 19, 4, 'Identify the front and back', 'முன்புறம் மற்றும் பின்புறத்தை அறியவும்', 'Child identifies front zipper.', 'முன்பக்க ஜிப்பை அடையாளம் காணவும்.', 'Find the front with the zipper!', 'ஜிப் உள்ள முன்பக்கத்தைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1905, 19, 5, 'Identify the collar/neck opening', 'காலர் பகுதியை அடையாளம் காணவும்', 'Child locates collar.', 'காலர் பகுதியைத் தொடவும்.', 'Find the collar at the top!', 'காலரைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1906, 19, 6, 'Identify the right sleeve', 'வலது கைக்குழாயை அறியவும்', 'Child finds right sleeve.', 'வலது கைக்குழாயைக் கண்டறியவும்.', 'Find the right sleeve!', 'வலது கைக் குழாயைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1907, 19, 7, 'Identify the left sleeve', 'இடது கைக்குழாயை அறியவும்', 'Child finds left sleeve.', 'இடது கைக்குழாயைக் கண்டறியவும்.', 'Find the left sleeve!', 'இடது கைக் குழாயைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1908, 19, 8, 'Put the right arm into the right sleeve', 'வலது கையை வலது குழாயில் நுழைக்கவும்', 'Child slips right arm in.', 'வலது கையை குழாயில் நுழைக்கவும்.', 'Slide your right arm into the sleeve!', 'வலது கையை உள்ளே நுழை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1909, 19, 9, 'Pull the right sleeve toward the shoulder', 'வலது குழாயை தோள்பட்டை வரை இழுக்கவும்', 'Child pulls sleeve up.', 'வலது கை சட்டையை தோள்பட்டை வரை மேலே இழுக்கவும்.', 'Pull the sleeve up high on your shoulder!', 'தோள்பட்டை வரை இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1910, 19, 10, 'Put the left arm into the left sleeve', 'இடது கையை இடது குழாயில் நுழைக்கவும்', 'Child slips left arm in.', 'இடது கையை குழாயில் நுழைக்கவும்.', 'Slide your left arm into the sleeve!', 'இடது கையை உள்ளே நுழை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1911, 19, 11, 'Pull the left sleeve toward the shoulder', 'இடது குழாயை தோள்பட்டை வரை இழுக்கவும்', 'Child pulls sleeve up.', 'இடது கை சட்டையை தோள்பட்டை வரை மேலே இழுக்கவும்.', 'Pull the left sleeve up high too!', 'இதையும் மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1912, 19, 12, 'Pull the jacket onto both shoulders', 'ஜாக்கெட்டை இரு தோள்களிலும் சீராக்கவும்', 'Child settles jacket.', 'ஜாக்கெட்டை இரு தோள்களிலும் சீராகப் பொருத்தவும்.', 'Settle the jacket on both shoulders!', 'தோள்களில் ஜாக்கெட்டை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1913, 19, 13, 'Straighten the jacket around the shoulders', 'தோள்பட்டையில் நேராக்கவும்', 'Child smooths fabric.', 'தோள்பட்டைப் பகுதியில் உள்ள சுருக்கங்களை நீக்கவும்.', 'Smooth out the shoulders!', 'தோள்பட்டையை சரிசெய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1914, 19, 14, 'Bring the two front sides together', 'முன்பக்க இரு விளிம்புகளையும் ஒன்றாகக் கொண்டு வரவும்', 'Child aligns zipper tracks.', 'இரு ஜிப் விளிம்புகளையும் ஒன்றாகக் கொண்டு வரவும்.', 'Bring the front zipper sides together!', 'இரு பக்கங்களையும் இணை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1915, 19, 15, 'Locate the zipper slider', 'ஜிப் ஸ்லைடரைக் கண்டறியவும்', 'Child locates slider.', 'நகரும் ஜிப் ஸ்லைடரைக் கண்டறியவும்.', 'Find the zipper slider at the bottom!', 'கீழே உள்ள ஜிப் ஸ்லைடரைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1916, 19, 16, 'Locate the zipper insertion pin', 'ஜிப் ஊசியைக் கண்டறியவும்', 'Child finds insertion pin.', 'மறுபுறம் உள்ள கம்பியைக் கண்டறியவும்.', 'Find the insertion pin on the other side!', 'மறுபக்கக் கம்பியைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1917, 19, 17, 'Hold the zipper slider with one hand', 'ஒரு கையால் ஜிப் ஸ்லைடரைப் பிடிக்கவும்', 'Child holds slider steady.', 'ஒரு கையால் ஸ்லைடரை கெட்டியாகப் பிடிக்கவும்.', 'Hold the zipper slider steady!', 'ஸ்லைடரை கெட்டியாகப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1918, 19, 18, 'Hold the insertion pin with the other hand', 'மற்றொரு கையால் ஊசியைப் பிடிக்கவும்', 'Child holds pin.', 'மற்றொரு கையால் கம்பியைப் பிடிக்கவும்.', 'Hold the pin with your other hand!', 'கம்பியைப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1919, 19, 19, 'Insert the pin completely into the zipper slider', 'ஊசியை ஸ்லைடருக்குள் முழுமையாக நுழைக்கவும்', 'Child pushes pin to bottom of slider.', 'கம்பியை ஸ்லைடருக்குள் கீழே வரை அழுத்தமாக நுழைக்கவும்.', 'Push the pin all the way into the slider!', 'கம்பியை உள்ளே தள்ளு! கிளிக்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1920, 19, 20, 'Hold the bottom of the jacket steady', 'ஜாக்கெட்டின் கீழ் பகுதியை அசையாமல் பிடிக்கவும்', 'Child anchors bottom edge.', 'ஜாக்கெட்டின் கீழ் விளிம்பை அசையாமல் பிடிக்கவும்.', 'Hold the bottom of the jacket steady!', 'கீழ் பகுதியை கெட்டியாகப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1921, 19, 21, 'Pull the zipper slider upward', 'ஜிப் ஸ்லைடரை மேல்நோக்கி இழுக்கவும்', 'Child pulls slider up.', 'ஸ்லைடரை மெதுவாக மேலே இழுக்கவும்.', 'Pull the zipper up!', 'ஜிப்பை மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1922, 19, 22, 'Continue pulling the zipper toward the chest', 'ஜிப்பை மார்பு வரை தொடர்ந்து இழுக்கவும்', 'Child pulls zipper past tummy to chest.', 'ஜிப்பை மார்பு பகுதி வரை மேலே இழுத்துச் செல்லவும்.', 'Zip up past your tummy to your chest!', 'மார்பு வரை மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1923, 19, 23, 'Pull the zipper toward the neck', 'ஜிப்பை கழுத்து வரை இழுக்கவும்', 'Child pulls toward neck.', 'ஜிப்பை கழுத்து வரை மேலே கொண்டு வரவும்.', 'Pull up toward your neck!', 'கழுத்து வரை மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1924, 19, 24, 'Release the zipper when the jacket is comfortably closed', 'வசதியாக மூடியவுடன் ஜிப்பை விடுவிக்கவும்', 'Child lets go of zipper tab.', 'போதுமான அளவு மூடியவுடன் ஜிப்பை விடவும்.', 'Stop and let go when it feels cozy!', 'போதுமானதும் ஜிப்பை விட்டுவிடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1925, 19, 25, 'Straighten the jacket around the shoulders', 'தோள்பட்டையில் நேராக்கவும்', 'Child smooths shoulders.', 'தோள்பட்டைப் பகுதியில் உள்ள சுருக்கங்களை நீக்கவும்.', 'Smooth out your shoulders!', 'தோள்பட்டையை சரிசெய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1926, 19, 26, 'Straighten the jacket around the waist', 'இடுப்பில் நேராக்கவும்', 'Child smooths bottom hem.', 'இடுப்புப் பகுதியில் சுருக்கங்களை நீக்கவும்.', 'Straighten around your waist!', 'இடுப்பில் நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1927, 19, 27, 'Check that the zipper is fully secured and the jacket is comfortable', 'ஜிப் சரியாகவும் வசதியாகவும் உள்ளதா எனப் பார்க்கவும்', 'Child confirms proper fit.', 'ஜாக்கெட் வசதியாக உள்ளதா என உறுதிசெய்யவும்.', 'All zipped up and cozy warm!', 'ஜாக்கெட் போட்டாச்சு! அருமை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2001, 20, 1, 'Stand or sit in front of the frock', 'பிராக்கின் முன் நிற்கவும் அல்லது அமரவும்', 'Child takes stable position facing frock.', 'பிராக் ஆடையின் முன் நேராக நிற்கவும் அல்லது அமரவும்.', 'Stand or sit in front of your dress!', 'உன் அழகான ஆடையின் முன் அமர்ந்து கொள்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2002, 20, 2, 'Look at the frock', 'பிராக்கைப் பார்க்கவும்', 'Child looks at dress design and openings.', 'பிராக் ஆடையைப் பார்க்கவும்.', 'Look at the pretty frock!', 'ஆடையைப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2003, 20, 3, 'Pick up the frock using both hands', 'இரு கைகளாலும் பிராக்கை எடுக்கவும்', 'Child lifts frock with two hands.', 'இரு கைகளாலும் ஆடையை எடுக்கவும்.', 'Pick up your frock with both hands!', 'இரு கைகளாலும் ஆடையை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2004, 20, 4, 'Identify the front and back', 'முன்புறம் மற்றும் பின்புறத்தை அறியவும்', 'Child finds front bodice and back tag.', 'முன்பக்க அமைப்பையும் பின்பக்க லேபிளையும் அடையாளம் காணவும்.', 'Find the front and back of the dress!', 'முன்பக்கத்தைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2005, 20, 5, 'Identify the neck opening', 'கழுத்துத் துவாரத்தை அறியவும்', 'Child locates neck hole.', 'கழுத்துத் துவாரத்தைக் கண்டறியவும்.', 'Find the neck opening at the top!', 'கழுத்துத் துவாரத்தைத் தொடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2006, 20, 6, 'Identify the right sleeve', 'வலது கைக்குழாயை அறியவும்', 'Child finds right sleeve.', 'வலது கைக்குழாயைக் கண்டறியவும்.', 'Find the right sleeve!', 'வலது கைக் குழாயைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2007, 20, 7, 'Identify the left sleeve', 'இடது கைக்குழாயை அறியவும்', 'Child finds left sleeve.', 'இடது கைக்குழாயைக் கண்டறியவும்.', 'Find the left sleeve!', 'இடது கைக் குழாயைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2008, 20, 8, 'Hold the frock near the shoulders', 'தோள்பட்டைப் பகுதிகளைப் பிடிக்கவும்', 'Child holds dress by shoulders.', 'ஆடையின் தோள்பட்டைப் பகுதிகளைப் பிடிக்கவும்.', 'Hold the frock by the shoulders!', 'தோள்பட்டையில் ஆடையைப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2009, 20, 9, 'Lift the frock to chest level', 'பிராக்கை மார்பு உயரத்திற்கு உயர்த்தவும்', 'Child raises dress up.', 'ஆடையை மார்பு உயரத்திற்கு தூக்கவும்.', 'Lift the dress up high to your chest!', 'மார்பு உயரத்திற்கு தூக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2010, 20, 10, 'Put the head through the neck opening', 'தலையை கழுத்துத் துவாரத்தில் நுழைக்கவும்', 'Child ducks head into neck hole.', 'தலையை கழுத்துத் துவாரத்திற்குள் நுழைக்கவும்.', 'Pop your head through the neck hole! Peekaboo!', 'தலையை உள்ளே நுழை! பீக்கபூ!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2011, 20, 11, 'Pull the frock down over the head', 'தலையைக் கடந்து பிராக்கை கீழே இழுக்கவும்', 'Child brings dress down around neck.', 'ஆடையை கழுத்து வரை கீழே இழுக்கவும்.', 'Pull the frock down around your neck!', 'தலையைக் கடந்து கீழே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2012, 20, 12, 'Find the right sleeve opening', 'வலது கை துவாரத்தைக் கண்டறியவும்', 'Child locates right armhole.', 'வலது கைத் துவாரத்தைக் கண்டறியவும்.', 'Find the right sleeve hole!', 'வலது கைத் துவாரத்தைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2013, 20, 13, 'Put the right arm through the right sleeve', 'வலது கையை வலது குழாயில் நுழைக்கவும்', 'Child passes right arm through.', 'வலது கையை குழாயில் நுழைத்து வெளியே கொண்டு வரவும்.', 'Push your right arm through!', 'வலது கையை உள்ளே நுழை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2014, 20, 14, 'Pull the right sleeve toward the shoulder', 'வலது குழாயை தோள்பட்டை வரை இழுக்கவும்', 'Child pulls right sleeve up onto shoulder.', 'வலது கையை தோள்பட்டை வரை மேலே இழுக்கவும்.', 'Pull the sleeve up on your shoulder!', 'தோள்பட்டை வரை இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2015, 20, 15, 'Find the left sleeve opening', 'இடது கை துவாரத்தைக் கண்டறியவும்', 'Child locates left armhole.', 'இடது கைத் துவாரத்தைக் கண்டறியவும்.', 'Find the left sleeve hole!', 'இடது கைத் துவாரத்தைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2016, 20, 16, 'Put the left arm through the left sleeve', 'இடது கையை இடது குழாயில் நுழைக்கவும்', 'Child passes left arm through.', 'இடது கையை குழாயில் நுழைத்து வெளியே கொண்டு வரவும்.', 'Push your left arm through!', 'இடது கையை உள்ளே நுழை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2017, 20, 17, 'Pull the left sleeve toward the shoulder', 'இடது குழாயை தோள்பட்டை வரை இழுக்கவும்', 'Child pulls left sleeve onto shoulder.', 'இடது கையை தோள்பட்டை வரை மேலே இழுக்கவும்.', 'Pull the other sleeve up on your shoulder!', 'இதையும் மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2018, 20, 18, 'Pull the upper part of the frock down over the trunk', 'மேற்பகுதியை உடல் மீது கீழே இழுக்கவும்', 'Child pulls bodice down over torso.', 'ஆடையின் மேற்பகுதியை உடல் மீது கீழ்நோக்கி இழுக்கவும்.', 'Pull the top of the frock down over your body!', 'உடல் மீது கீழே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2019, 20, 19, 'Pull the front of the frock down', 'பிராக்கின் முன்பகுதியை கீழே இழுக்கவும்', 'Child smooths front skirt down.', 'ஆடையின் முன்பக்கத்தை கீழ்நோக்கி இழுக்கவும்.', 'Pull the front of the dress down!', 'முன்பக்கத்தை கீழே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2020, 20, 20, 'Pull the back of the frock down', 'பிராக்கின் பின்பகுதியை கீழே இழுக்கவும்', 'Child smooths back skirt down.', 'ஆடையின் பின்பக்கத்தை கீழ்நோக்கி இழுக்கவும்.', 'Pull the back of the dress down!', 'பின்பக்கத்தை கீழே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2021, 20, 21, 'Straighten the frock around the shoulders', 'தோள்பட்டையில் நேராக்கவும்', 'Child smooths shoulders.', 'தோள்பட்டைப் பகுதியில் சுருக்கங்களை நீக்கவும்.', 'Fix the frock at your shoulders!', 'தோள்பட்டையை சரிசெய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2022, 20, 22, 'Straighten the frock around the waist/hips', 'இடுப்பு மற்றும் கீழ் பகுதியில் நேராக்கவும்', 'Child adjusts waistline.', 'இடுப்புப் பகுதியில் ஆடையை சுருக்கமின்றி சரிசெய்யவும்.', 'Straighten around your waist!', 'இடுப்பில் நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2023, 20, 23, 'Smooth the lower part of the frock', 'பாவாடைப் பகுதியை நேராக்கவும்', 'Child smooths flair of dress.', 'ஆடையின் கீழ் பாவாடைப் பகுதியை சுருக்கமின்றி சரிசெய்யவும்.', 'Smooth out your pretty dress!', 'ஆடையை அழகாக நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2024, 20, 24, 'Check that the frock is correctly positioned, comfortable, and ready to wear', 'பிராக் வசதியாகவும் அழகாகவும் உள்ளதா எனப் பார்க்கவும்', 'Child spins or checks mirror.', 'கண்ணாடியில் பார்த்து ஆடை அழகாக உள்ளதை உறுதிசெய்யவும்.', 'Twirl around! You look like a princess!', 'சுற்றிப் பார்! இளவரசி போல அழகாக உள்ளாய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2101, 21, 1, 'Move to a private changing area', 'தனிப்பட்ட உடை மாற்றும் அறைக்குச் செல்லவும்', 'Guide child to private area for dignity.', 'குழந்தையை தனிப்பட்ட உடை மாற்றும் இடத்திற்கு அழைத்துச் செல்லவும்.', 'Let us step into your private changing space!', 'உடை மாற்றும் அறைக்கு வா!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2102, 21, 2, 'Pick up the vest/camisole', 'கேமிசோலை எடுக்கவும்', 'Child picks up clean camisole.', 'சுத்தமான கேமிசோல் உள்சட்டையை எடுக்கவும்.', 'Pick up your clean camisole!', 'கேமிசோலை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2103, 21, 3, 'Identify the front and back', 'முன்புறம் மற்றும் பின்புறத்தை அறியவும்', 'Child finds back tag.', 'பின்பக்க லேபிளை அடையாளம் காணவும்.', 'Find the tag on the back!', 'பின்பக்க லேபிளைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2104, 21, 4, 'Identify the neck opening', 'கழுத்துத் துவாரத்தை அறியவும்', 'Child locates neck scoop.', 'கழுத்துத் துவாரத்தைக் கண்டறியவும்.', 'Find the neck hole!', 'கழுத்துத் துவாரத்தைத் தொடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2105, 21, 5, 'Identify the right and left arm openings/straps', 'இரு தோள்பட்டைப் பட்டைகளையும் அறியவும்', 'Child finds shoulder straps.', 'இரு தோள்பட்டைப் பட்டைகளையும் அடையாளம் காணவும்.', 'Find both shoulder straps!', 'இரு பட்டைகளையும் தொடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2106, 21, 6, 'Hold the garment near the shoulder areas', 'தோள்பட்டைப் பகுதிகளைப் பிடிக்கவும்', 'Child holds straps.', 'கேமிசோலின் மேல் பட்டைகளைப் பிடிக்கவும்.', 'Hold the camisole by the straps!', 'பட்டைகளில் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2107, 21, 7, 'Lift the garment to chest level', 'மார்பு உயரத்திற்கு உயர்த்தவும்', 'Child lifts camisole.', 'கேமிசோலை மார்பு உயரத்திற்கு தூக்கவும்.', 'Lift it up to your chest!', 'மார்பு உயரத்திற்கு தூக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2108, 21, 8, 'Put the head through the neck opening', 'தலையை கழுத்துத் துவாரத்தில் நுழைக்கவும்', 'Child ducks head through neck hole.', 'தலையை கழுத்துத் துவாரத்திற்குள் நுழைக்கவும்.', 'Pop your head through the neck hole! Peekaboo!', 'தலையை உள்ளே நுழை! எட்டிப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2109, 21, 9, 'Pull the garment down over the head', 'தலையைக் கடந்து கீழே இழுக்கவும்', 'Child brings camisole onto neck.', 'கேமிசோலை கழுத்து வரை கீழே இழுக்கவும்.', 'Pull it down around your neck!', 'தலையைக் கடந்து கீழே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2110, 21, 10, 'Find the right arm opening/strap', 'வலது கைத் துவாரத்தைக் கண்டறியவும்', 'Child finds right strap.', 'வலது பட்டையைக் கண்டறியவும்.', 'Find the right strap hole!', 'வலது பட்டையைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2111, 21, 11, 'Put the right arm through the opening', 'வலது கையை துவாரத்தில் நுழைக்கவும்', 'Child puts right arm through.', 'வலது கையை துவாரத்தில் நுழைத்து வெளியே கொண்டு வரவும்.', 'Push your right arm through!', 'வலது கையை உள்ளே நுழை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2112, 21, 12, 'Adjust the garment toward the right shoulder', 'வலது தோள்பட்டையில் பட்டையை வைக்கவும்', 'Child positions strap on right shoulder.', 'பட்டையை வலது தோள்பட்டையில் சீராக வைக்கவும்.', 'Settle the strap on your right shoulder!', 'தோள்பட்டை மேல் பட்டையை வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2113, 21, 13, 'Find the left arm opening/strap', 'இடது கைத் துவாரத்தைக் கண்டறியவும்', 'Child finds left strap.', 'இடது பட்டையைக் கண்டறியவும்.', 'Find the left strap hole!', 'இடது பட்டையைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2114, 21, 14, 'Put the left arm through the opening', 'இடது கையை துவாரத்தில் நுழைக்கவும்', 'Child puts left arm through.', 'இடது கையை துவாரத்தில் நுழைத்து வெளியே கொண்டு வரவும்.', 'Push your left arm through!', 'இடது கையை உள்ளே நுழை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2115, 21, 15, 'Adjust the garment toward the left shoulder', 'இடது தோள்பட்டையில் பட்டையை வைக்கவும்', 'Child positions strap on left shoulder.', 'பட்டையை இடது தோள்பட்டையில் சீராக வைக்கவும்.', 'Settle the strap on your left shoulder!', 'தோள்பட்டை மேல் பட்டையை வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2116, 21, 16, 'Pull the garment down over the chest', 'மார்பின் மேல் கீழே இழுக்கவும்', 'Child smooths fabric over chest.', 'கேமிசோலை மார்புப் பகுதியில் கீழ்நோக்கி இழுக்கவும்.', 'Pull the camisole down over your chest!', 'மார்பின் மேல் கீழே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2117, 21, 17, 'Pull it down over the abdomen', 'வயிற்றின் மேல் கீழே இழுக்கவும்', 'Child pulls lower hem past tummy.', 'கேமிசோலின் கீழ் விளிம்பை தொப்புளுக்குக் கீழே இழுக்கவும்.', 'Pull it all the way down over your tummy!', 'வயிற்றுக்கு கீழே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2118, 21, 18, 'Straighten the shoulder straps/upper portion', 'தோள்பட்டைப் பட்டைகளை நேராக்கவும்', 'Child smooths flat straps.', 'தோள்பட்டைப் பட்டைகள் முறுக்காமல் தட்டையாக உள்ளதா என சரிசெய்யவும்.', 'Make sure both straps are straight and flat!', 'பட்டைகளை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2119, 21, 19, 'Straighten the lower edge around the waist', 'இடுப்புப் பகுதியில் கீழ் விளிம்பை நேராக்கவும்', 'Child smooths hem around waist.', 'கீழ் விளிம்பை இடுப்பில் சுருக்கமின்றி சரிசெய்யவும்.', 'Straighten the bottom around your waist!', 'கீழ் விளிம்பை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2120, 21, 20, 'Check that the garment is correctly positioned and comfortable', 'உள்சட்டை வசதியாக உள்ளதா என சரிபார்க்கவும்', 'Child confirms comfort.', 'கேமிசோல் வசதியாக உள்ளதை உறுதிசெய்யவும்.', 'Comfy and neat! Ready for your top or dress!', 'உள்சட்டை போட்டாச்சு! அருமை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2201, 22, 1, 'Stand or sit in front of the skirt', 'பாவாடorder முன் நிற்கவும் அல்லது அமரவும்', 'Child faces skirt placed flat.', 'பாவாடைக்கு முன் நேராக நிற்கவும் அல்லது அமரவும்.', 'Stand or sit in front of your skirt!', 'பாவாடை முன் அமர்ந்து கொள்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2202, 22, 2, 'Look at the skirt', 'பாவாடையைப் பார்க்கவும்', 'Child examines skirt waistband and ties.', 'பாவாடையின் இடுப்புப் பட்டை மற்றும் நாடாவைப் பார்க்கவும்.', 'Look at the skirt!', 'பாவாடையைப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2203, 22, 3, 'Pick up the skirt using both hands', 'இரு கைகளாலும் பாவாடையை எடுக்கவும்', 'Child lifts skirt with two hands.', 'இரு கைகளாலும் பாவாடையை எடுக்கவும்.', 'Pick up your skirt with both hands!', 'இரு கைகளாலும் பாவாடையை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2204, 22, 4, 'Identify the front and back of the skirt', 'முன்புறம் மற்றும் பின்புறத்தை அறியவும்', 'Child locates front drawstring cords.', 'முன்பக்க நாடாவையும் பின்பக்க அமைப்பையும் அடையாளம் காணவும்.', 'Find the drawstrings in the front!', 'முன்பக்க நாடாவைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2205, 22, 5, 'Find the waistband', 'இடுப்புப் பட்டையைக் கண்டறியவும்', 'Child locates top waistband.', 'மேல் இடுப்புப் பட்டையைத் தொடவும்.', 'Find the waistband at the top!', 'இடுப்புப் பட்டையைத் தொடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2206, 22, 6, 'Find the two ends of the drawstring', 'நாடாவின் இரு முனைகளையும் கண்டறியவும்', 'Child locates untied cords.', 'நாடாவின் இரு முனைகளையும் கைகளில் எடுக்கவும்.', 'Find both ends of the string!', 'இரு நாடா முனைகளையும் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2207, 22, 7, 'Hold the waistband with both hands', 'இரு கைகளாலும் இடுப்புப் பட்டையைப் பிடிக்கவும்', 'Child holds waistband open.', 'இடுப்புப் பட்டையை இரு கைகளாலும் பிடிக்கவும்.', 'Hold the waistband with both hands!', 'இரு கைகளாலும் பட்டையைப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2208, 22, 8, 'Open the waistband sufficiently', 'இடுப்புப் பட்டையை போதுமான அளவு விரிக்கவும்', 'Child widens opening.', 'இடுப்புப் பட்டையை கால்கள் நுழையுமாறு விரிக்கவும்.', 'Open the waistband nice and wide!', 'பட்டையை அகலமாக விரி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2209, 22, 9, 'Step one foot into the skirt', 'ஒரு காலை பாவாடைக்குள் வைக்கவும்', 'Child steps first foot in.', 'ஒரு பாதத்தை பாவாடைக்குள் வைக்கவும்.', 'Step one foot into the skirt!', 'ஒரு காலை உள்ளே வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2210, 22, 10, 'Step the other foot into the skirt', 'மற்றொரு காலையும் பாவாடைக்குள் வைக்கவும்', 'Child steps second foot in.', 'அடுத்த பாதத்தையும் பாவாடைக்குள் வைக்கவும்.', 'Step your other foot in too!', 'அடுத்த காலையும் உள்ளே வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2211, 22, 11, 'Pull the skirt upward to the knees', 'முழங்கால் வரை பாவாடையை மேலே இழுக்கவும்', 'Child gathers skirt to knees.', 'பாவாடையை முழங்கால் வரை மேலே இழுக்கவும்.', 'Pull the skirt up to your knees!', 'முழங்கால் வரை இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2212, 22, 12, 'Pull the skirt upward toward the hips', 'இடுப்பு வரை பாவாடையை மேலே இழுக்கவும்', 'Child gathers skirt past thighs to hips.', 'பாவாடையை தொடை வழியே இடுப்பு வரை மேலே இழுக்கவும்.', 'Pull the skirt up to your hips!', 'இடுப்பு வரை இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2213, 22, 13, 'Pull the waistband up to the waist', 'இடுப்புப் பட்டையை இடுப்பில் வைக்கவும்', 'Child positions waistband at natural waist.', 'இடுப்புப் பட்டையை இடுப்பில் சரியாகப் பொருத்தவும்.', 'Pull the waistband right up to your waist!', 'இடுப்பில் சரியாக வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2214, 22, 14, 'Check that the waistband is positioned evenly', 'இடுப்புப் பட்டை சீராக உள்ளதா என சரிபார்க்கவும்', 'Child checks waist is level.', 'இடுப்புப் பட்டை சரிசமமாக உள்ளதா எனப் பார்க்கவும்.', 'Make sure the waistband is even!', 'இடுப்புப் பட்டையை சமமாக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2215, 22, 15, 'Find both ends of the drawstring', 'நாடாவின் இரு முனைகளையும் எடுக்கவும்', 'Child takes left and right cords.', 'இரு நாடா முனைகளையும் கைகளில் எடுக்கவும்.', 'Hold both ends of the string!', 'இரு நாடாக்களையும் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2216, 22, 16, 'Hold one end in each hand', 'ஒவ்வொரு கையிலும் ஒரு முனையைப் பிடிக்கவும்', 'Child separates cords.', 'ஒவ்வொரு கையிலும் ஒரு நாடாவைப் பிடிக்கவும்.', 'Hold one string in each hand!', 'ஒவ்வொரு கையிலும் ஒரு நாடாவைப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2217, 22, 17, 'Pull the two ends to adjust the waistband', 'இடுப்புக்கு தகுந்தவாறு நாடாக்களை இழுக்கவும்', 'Child tightens cords laterally.', 'இடுப்புக்குத் தகுந்தவாறு இரு நாடாக்களையும் இழுத்து இறுக்கவும்.', 'Pull both strings to tighten the waist!', 'நாடாக்களை இழுத்து இறுக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2218, 22, 18, 'Cross one drawstring over the other', 'ஒரு நாடாவை மற்றொன்றின் மேல் குறுக்காக வைக்கவும்', 'Child crosses strings forming an X.', 'ஒரு நாடாவை மற்றொன்றின் மீது குறுக்காக வைக்கவும்.', 'Cross one string over the other!', 'நாடாக்களை குறுக்காக வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2219, 22, 19, 'Make a loop with one end', 'ஒரு முனையில் சுருக்கு வளையம் செய்யவும்', 'Child forms loop like bunny ear.', 'ஒரு நாடாவில் சிறிய வளையம் உருவாக்கவும்.', 'Make a loop like a bunny ear!', 'ஒரு முயல் காது போல வளையம் செய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2220, 22, 20, 'Wrap the other end around the loop', 'மற்றொரு நாடாவை வளையத்தைச் சுற்றி சுற்றவும்', 'Child winds second string around loop base.', 'மற்றொரு நாடாவை அந்த வளையத்தைச் சுற்றி சுற்றவும்.', 'Wrap the other string around the loop!', 'சுற்றி வளைத்து எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2221, 22, 21, 'Push the end through to form a knot/bow', 'முனையை துளை வழியே தள்ளி முடிச்சு போடவும்', 'Child pushes loop through.', 'நாடாவை நடுவில் தள்ளி முடிச்சு உருவாக்கவும்.', 'Push it through to make the bow!', 'உள்ளே தள்ளி முடிச்சு போடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2222, 22, 22, 'Pull the loops/ends to secure the drawstring', 'முடிச்சை இறுக்க இரு வளையங்களையும் இழுக்கவும்', 'Child pulls loops tight.', 'முடிச்சை உறுதியாக இழுத்து இறுக்கவும்.', 'Pull both loops tight!', 'இரு பக்கமும் இழுத்து கெட்டியாக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2223, 22, 23, 'Check that the skirt is secure', 'பாவாடை நழுவாமல் உள்ளதா என சரிபார்க்கவும்', 'Child verifies bow holds waistband firmly.', 'பாவாடை நழுவாமல் சரியாக உள்ளதா என உறுதிசெய்யவும்.', 'Make sure the skirt stays on safely!', 'சரியாக உள்ளதா எனப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2224, 22, 24, 'Straighten the waistband', 'இடுப்புப் பட்டையை நேராக்கவும்', 'Child smooths gathers.', 'இடுப்புப் பட்டையை சுருக்கமின்றி நேராக்கவும்.', 'Straighten your waistband!', 'இடுப்புப் பட்டையை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2225, 22, 25, 'Smooth the skirt around the hips', 'இடுப்பில் பாவாடையை நேராக்கவும்', 'Child smooths upper skirt.', 'இடுப்புப் பகுதியில் பாவாடையை சுருக்கமின்றி சரிசெய்யவும்.', 'Smooth down around your hips!', 'இடுப்பில் நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2226, 22, 26, 'Straighten the lower part of the skirt', 'பாவாடையின் கீழ் பகுதியை நேராக்கவும்', 'Child smooths lower hem.', 'பாவாடையின் கீழ் விளிம்பை சுருக்கமின்றி சரிசெய்யவும்.', 'Smooth down the skirt flair!', 'பாவாடையை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2227, 22, 27, 'Check that the skirt is comfortable and correctly positioned', 'பாவாடை வசதியாகவும் சரியாகவும் உள்ளதா எனப் பார்க்கவும்', 'Child spins and confirms comfort.', 'சுற்றிப் பார்த்து பாவாடை வசதியாக உள்ளதை உறுதிசெய்யவும்.', 'Tied perfectly! You look lovely in your skirt!', 'அருமையாக முடிச்சு போட்டாச்சு! மிக அழகு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2301, 23, 1, 'Stand or sit in front of the shorts', 'அரைக்கால் சட்டையின் முன் நிற்கவும் அல்லது அமரவும்', 'Child faces shorts placed flat.', 'அரைக்கால் சட்டைக்கு முன் நேராக நிற்கவும் அல்லது அமரவும்.', 'Stand or sit in front of your shorts!', 'அரைக்கால் சட்டை முன் நில்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2302, 23, 2, 'Look at the shorts', 'அரைக்கால் சட்டையைப் பார்க்கவும்', 'Child observes shorts.', 'அரைக்கால் சட்டையைப் பார்க்கவும்.', 'Look at the shorts!', 'அரைக்கால் சட்டையைப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2303, 23, 3, 'Pick up the shorts using both hands', 'இரு கைகளாலும் சட்டையை எடுக்கவும்', 'Child lifts shorts.', 'இரு கைகளாலும் அரைக்கால் சட்டையை எடுக்கவும்.', 'Pick up your shorts with both hands!', 'இரு கைகளாலும் சட்டையை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2304, 23, 4, 'Identify the front and back', 'முன்புறம் மற்றும் பின்புறத்தை அறியவும்', 'Child finds back tag.', 'பின்பக்க லேபிளை அடையாளம் காணவும்.', 'Find the tag on the back!', 'பின்பக்க லேபிளைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2305, 23, 5, 'Find the waistband', 'இடுப்புப் பட்டையைக் கண்டறியவும்', 'Child locates elastic waistband.', 'எலாஸ்டிக் இடுப்புப் பட்டையைத் தொடவும்.', 'Find the waistband!', 'இடுப்புப் பட்டையைத் தொடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2306, 23, 6, 'Find the right leg opening', 'வலது கால் துவாரத்தைக் கண்டறியவும்', 'Child finds right opening.', 'வலது கால் துவாரத்தைக் கண்டறியவும்.', 'Find the right leg hole!', 'வலது கால் துவாரத்தைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
