INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2410, 24, 10, 'Step one foot into the correct leg opening', 'ஒரு காலை துவாரத்தில் வைக்கவும்', 'Child steps foot in.', 'ஒரு பாதத்தை உள்ளே வைக்கவும்.', 'Step one foot into the leg hole!', 'ஒரு காலை உள்ளே வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
