INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2413, 24, 13, 'Push the second foot through', 'இரண்டாவது பாதத்தையும் வெளியே தள்ளவும்', 'Child pushes second foot through cuff.', 'இரண்டாவது பாதத்தை கீழே வெளியே தள்ளவும்.', 'Push your other foot all the way through!', 'மற்றொரு பாதத்தை வெளியே தள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2414, 24, 14, 'Pull the jeans up to the knees', 'ஜீன்ஸை முழங்கால் வரை மேலே இழுக்கவும்', 'Child pulls denim to knees.', 'ஜீன்ஸை முழங்கால் வரை இழுக்கவும்.', 'Pull the jeans up to your knees!', 'முழங்கால் வரை இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2415, 24, 15, 'Pull the jeans upward toward the thighs', 'தொடை வரை ஜீன்ஸை மேலே இழுக்கவும்', 'Child pulls denim onto thighs.', 'ஜீன்ஸை தொடை வரை மேலே இழுக்கவும்.', 'Pull the jeans up to your thighs!', 'தொடை வரை மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
