INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2417, 24, 17, 'Pull the waistband up toward the waist', 'இடுப்புப் பட்டையை இடுப்பு வரை இழுக்கவும்', 'Child pulls waistband over hips.', 'இடுப்புப் பட்டையை இடுப்பு வரை உயர்த்தவும்.', 'Pull the waistband up to your waist!', 'இடுப்பு வரை மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2418, 24, 18, 'Check that the waistband is positioned evenly', 'இடுப்புப் பட்டை சீராக உள்ளதா என சரிபார்க்கவும்', 'Child checks level waistband.', 'இடுப்புப் பட்டை சமமாக உள்ளதா எனப் பார்க்கவும்.', 'Make sure the waistband is even!', 'இடுப்புப் பட்டையை சமமாக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
