INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2421, 24, 21, 'Pull the zipper upward', 'ஜிப்பை மேல்நோக்கி இழுக்கவும்', 'Child starts pulling slider.', 'ஜிப்பை மேல்நோக்கி இழுக்கவும்.', 'Pull the zipper upward!', 'ஜிப்பை மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2422, 24, 22, 'Continue pulling until the zipper is fully closed', 'ஜிப்பை முழுமையாக மூடும் வரை தொடர்ந்து இழுக்கவும்', 'Child pulls zipper to top stop.', 'ஜிப்பை முழுமையாக மேல் வரை இழுத்து மூடவும்.', 'Keep pulling until it is fully zipped!', 'மேல் வரை முழுமையாக இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2423, 24, 23, 'Locate the button', 'பொத்தானைக் கண்டறியவும்', 'Child finds button.', 'பொத்தானைக் கண்டறியவும்.', 'Find the button!', 'பொத்தானைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2424, 24, 24, 'Locate the corresponding buttonhole', 'பொத்தான் துளையைக் கண்டறியவும்', 'Child finds matching hole.', 'பொத்தான் துளையைக் கண்டறியவும்.', 'Find the buttonhole!', 'துளையைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2425, 24, 25, 'Hold the waistband near the button', 'பொத்தானுக்கு அருகில் இடுப்புப் பட்டையைப் பிடிக்கவும்', 'Child braces buttonhole fabric.', 'துளை உள்ள பகுதியை ஒரு கையால் பிடிக்கவும்.', 'Hold the waistband near the button!', 'இடுப்புப் பட்டையை கெட்டியாகப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2426, 24, 26, 'Push the button through the buttonhole', 'பொத்தானை துளைக்குள் நுழைக்கவும்', 'Child pushes button through hole.', 'பொத்தானை துளைக்குள் தள்ளவும்.', 'Push the button through the hole!', 'பொத்தானை துளைக்குள் தள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2427, 24, 27, 'Pull the waistband to secure the button', 'பொத்தானை உறுதியாக மாட்டவும்', 'Child pulls denim to fasten.', 'பொத்தான் முழுமையாக மாட்டப்பட்டுள்ளதை உறுதிசெய்யவும்.', 'Pull to fasten the button tight!', 'பொத்தானை மாட்டிவிடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2428, 24, 28, 'Check that the zipper and button are secured', 'ஜிப் மற்றும் பொத்தான் பூட்டப்பட்டுள்ளதை சரிபார்க்கவும்', 'Child confirms closures.', 'இரண்டும் சரியாக மூடப்பட்டுள்ளதா எனப் பார்க்கவும்.', 'Check that your button and zipper are fastened!', 'பொத்தானும் ஜிப்பும் சரியா எனப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2429, 24, 29, 'Straighten the waistband and smooth jeans comfortably', 'இடுப்பு மற்றும் கால்களில் நேராக்கி வசதியை உறுதிசெய்யவும்', 'Child smooths denim down legs.', 'சுருக்கங்களை கை வைத்து நேராக்கி வசதியை உறுதிசெய்யவும்.', 'Smooth them down! You look fantastic in your jeans!', 'ஜீன்ஸ் மிக அருமையாக உள்ளது!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2501, 25, 1, 'Move to a private changing area', 'தனிப்பட்ட அறைக்குச் செல்லவும்', 'Guide child to private area for dignity.', 'குழந்தையை தனிப்பட்ட உடை மாற்றும் இடத்திற்கு அழைத்துச் செல்லவும்.', 'Let us step into your private dressing space!', 'உடை மாற்றும் அறைக்கு வா!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2502, 25, 2, 'Pick up the underwear', 'உள்ளாடையை எடுக்கவும்', 'Child picks up clean panties.', 'சுத்தமான உள்ளாடையை எடுக்கவும்.', 'Pick up your clean panties!', 'உள்ளாடையை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2503, 25, 3, 'Identify the front and back', 'முன்புறம் மற்றும் பின்புறத்தை அறியவும்', 'Child finds back tag.', 'பின்பக்க லேபிளை அடையாளம் காணவும்.', 'Find the tag on the back!', 'பின்பக்க லேபிளைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2504, 25, 4, 'Identify the waistband', 'இடுப்புப் பட்டையைக் கண்டறியவும்', 'Child locates elastic top.', 'எலாஸ்டிக் இடுப்புப் பட்டையைத் தொடவும்.', 'Find the waistband!', 'இடுப்புப் பட்டையைத் தொடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2505, 25, 5, 'Identify the right and left leg openings', 'இரு கால் துவாரங்களையும் அறியவும்', 'Child locates both leg openings.', 'இரு கால் துவாரங்களையும் அடையாளம் காணவும்.', 'Find both leg holes!', 'இரு துவாரங்களையும் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2506, 25, 6, 'Hold the waistband with both hands', 'இரு கைகளாலும் இடுப்புப் பட்டையைப் பிடிக்கவும்', 'Child grips waistband sides.', 'இடுப்புப் பட்டையை இரு கைகளாலும் பிடிக்கவும்.', 'Hold the waistband with both hands!', 'இரு கைகளாலும் பட்டையைப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2507, 25, 7, 'Open the waistband', 'இடுப்புப் பட்டையை விரிக்கவும்', 'Child stretches opening wide.', 'இடுப்புப் பட்டையை விரிக்கவும்.', 'Stretch the waistband open wide!', 'பட்டையை அகலமாக விரி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2508, 25, 8, 'Step one foot into the corresponding leg opening', 'ஒரு காலை துவாரத்தில் வைக்கவும்', 'Child steps foot in.', 'ஒரு பாதத்தை உள்ளே வைக்கவும்.', 'Step one foot into the leg hole!', 'ஒரு காலை உள்ளே வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2509, 25, 9, 'Push the foot through the opening', 'பாதத்தை துவாரம் வழியே வெளியே தள்ளவும்', 'Child extends foot completely through.', 'பாதத்தை வெளியே தள்ளவும்.', 'Push your foot all the way through!', 'பாதத்தை வெளியே தள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2510, 25, 10, 'Step the other foot into the other leg opening', 'மற்றொரு காலை அடுத்த துவாரத்தில் வைக்கவும்', 'Child steps second foot in.', 'அடுத்த பாதத்தை மற்ற துவாரத்தில் வைக்கவும்.', 'Step your other foot in!', 'அடுத்த காலை உள்ளே வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2511, 25, 11, 'Push the second foot through', 'இரண்டாவது பாதத்தையும் வெளியே தள்ளவும்', 'Child pushes foot through.', 'இரண்டாவது பாதத்தை வெளியே தள்ளவும்.', 'Push your other foot all the way through!', 'மறு பாதத்தையும் வெளியே தள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2512, 25, 12, 'Pull the underwear upward to the knees', 'முழங்கால் வரை மேலே இழுக்கவும்', 'Child pulls panties to knees.', 'உள்ளாடையை முழங்கால் வரை இழுக்கவும்.', 'Pull up to your knees!', 'முழங்கால் வரை இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2513, 25, 13, 'Pull the underwear upward toward the thighs', 'தொடை வரை மேலே இழுக்கவும்', 'Child pulls panties onto thighs.', 'உள்ளாடையை தொடை வரை இழுக்கவும்.', 'Pull up to your thighs!', 'தொடை வரை இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2514, 25, 14, 'Pull the waistband upward toward the waist', 'இடுப்பு வரை மேலே இழுக்கவும்', 'Child pulls waistband to waist.', 'இடுப்புப் பட்டையை இடுப்பு வரை மேலே இழுக்கவும்.', 'Pull the waistband up to your waist!', 'இடுப்பு வரை மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2515, 25, 15, 'Adjust the front and back', 'முன்புறம் மற்றும் பின்புறத்தை சரிசெய்யவும்', 'Child balances coverage.', 'முன்புறமும் பின்புறமும் சீராக உள்ளதா என சரிசெய்யவும்.', 'Adjust the front and back evenly!', 'முன்பக்கமும் பின்பக்கமும் சரிசெய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2516, 25, 16, 'Check that both legs are correctly positioned', 'இரு கால்களும் சரியாக உள்ளதா எனப் பார்க்கவும்', 'Child checks leg openings fit comfortably.', 'கால் துவாரங்கள் வசதியாக உள்ளதா எனப் பார்க்கவும்.', 'Make sure both legs feel comfy!', 'இரு கால்களையும் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2517, 25, 17, 'Straighten the waistband around the waist', 'இடுப்புப் பட்டையை நேராக்கவும்', 'Child flattens elastic.', 'இடுப்புப் பட்டையை சுருக்கமின்றி நேராக்கவும்.', 'Straighten your waistband flat!', 'இடுப்புப் பட்டையை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2518, 25, 18, 'Smooth the underwear around the hips and thighs', 'இடுப்பு மற்றும் தொடைகளில் நேராக்கவும்', 'Child smooths fabric.', 'சுருக்கங்களை கை வைத்து நீக்கவும்.', 'Smooth down the sides!', 'பக்கவாட்டில் நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2519, 25, 19, 'Check that the underwear is comfortable and secure', 'உள்ளாடை வசதியாகவும் சரியாகவும் உள்ளதா என உறுதிசெய்யவும்', 'Child confirms comfort.', 'உள்ளாடை வசதியாக உள்ளதை உறுதிசெய்யவும்.', 'Snug and comfortable! Great job!', 'உள்ளாடை வசதியாக உள்ளது! சபாஷ்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2520, 25, 20, 'Put the outer clothing over the undergarment', 'உள்ளாடையின் மேல் வெளிப்புற உடையை அணியவும்', 'Child is ready for skirt or pants.', 'இப்போது பாவாடை அல்லது கால்சட்டை அணியத் தயாராகலாம்.', 'Now you are ready for your skirt or pants!', 'இப்போது அடுத்த உடை போடலாம்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (801, 8, 1, 'Sit in a stable position and look at the socks', 'நிலையாக அமர்ந்து காலுறைகளைப் பார்க்கவும்', 'Child sits securely on chair or floor and views socks.', 'குழந்தை நிலையாக அமர்ந்து காலுறைகளைப் பார்க்க வேண்டும்.', 'Sit nice and steady and look at your socks!', 'நிலையாக அமர்ந்து காலுறைகளைப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (802, 8, 2, 'Pick up one sock', 'ஒரு காலுறையை எடுக்கவும்', 'Child selects and lifts one sock.', 'ஒரு காலுறையைக் கையில் எடுக்கவும்.', 'Pick up one sock!', 'ஒரு காலுறையை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (803, 8, 3, 'Identify the top/opening of the sock', 'காலுறையின் மேல் துவாரத்தைக் கண்டறியவும்', 'Child finds opening cuff of sock.', 'காலுறையின் மேல் திறப்புப் பகுதியைத் தொடவும்.', 'Find the opening at the top!', 'மேலே உள்ள திறப்பைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (804, 8, 4, 'Identify the heel area of the sock', 'குதிக்கால் பகுதியை அடையாளம் காணவும்', 'Child locates curved heel cup.', 'வளைந்த குதிக்கால் பகுதியை அடையாளம் காணவும்.', 'Find the heel curve on the sock!', 'குதிக்கால் வளைவைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (805, 8, 5, 'Hold the sock opening with both hands', 'இரு கைகளாலும் காலுறை துவாரத்தைப் பிடிக்கவும்', 'Child places both thumbs inside sock opening.', 'இரு கட்டை விரல்களையும் காலுறைக்குள் வைத்துப் பிடிக்கவும்.', 'Hold the opening with both hands!', 'இரு கைகளாலும் திறப்பைப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (806, 8, 6, 'Stretch the sock opening slightly', 'துவாரத்தை சற்று விரிக்கவும்', 'Child stretches elastic cuff.', 'காலுறை திறப்பை சற்று அகலமாக விரிக்கவும்.', 'Stretch the sock open wide!', 'திறப்பை அகலமாக விரி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (807, 8, 7, 'Open the sock sufficiently', 'காலுறைக்குள் பாதம் நுழைய போதுமான அளவு திறக்கவும்', 'Child scrunches sock ready for toes.', 'விரல்கள் நுழையும் வரை காலுறையைச் சுருக்கித் திறக்கவும்.', 'Scrunch the sock down to the toes!', 'காலுறையை விரிக்கவும்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (808, 8, 8, 'Lift one foot toward the hands', 'ஒரு பாதத்தை கைகளை நோக்கி உயர்த்தவும்', 'Child flexes hip and knee to bring foot up.', 'ஒரு பாதத்தை மேலே உயர்த்தவும்.', 'Lift your foot up toward your hands!', 'பாதத்தை மேலே தூக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (809, 8, 9, 'Place the toes into the sock opening', 'கால் விரல்களை காலுறைக்குள் வைக்கவும்', 'Child aligns toes with sock opening.', 'கால் விரல்களை காலுறைத் துவாரத்தில் வைக்கவும்.', 'Put your toes right into the sock!', 'விரல்களை உள்ளே வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (810, 8, 10, 'Push the toes further into the sock', 'விரல்களை காலுறையின் நுனி வரை தள்ளவும்', 'Child pushes toes fully into toe seam.', 'கால் விரல்களை காலுறையின் நுனி வரை தள்ளவும்.', 'Push your toes all the way to the tip!', 'நுனி வரை விரல்களைத் தள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (811, 8, 11, 'Pull the sock over the heel', 'குதிக்கால் மேல் காலுறையை இழுக்கவும்', 'Child guides heel cup past back of foot.', 'குதிக்கால் மேல் காலுறையை இழுத்து மாட்டவும்.', 'Pull the sock snug over your heel!', 'குதிக்கால் மேல் இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (812, 8, 12, 'Pull the sock upward toward the ankle', 'காலுறையை கணுக்கால் வரை மேலே இழுக்கவும்', 'Child pulls cuff up around ankle/calf.', 'காலுறையை கணுக்கால் வரை மேலே இழுக்கவும்.', 'Pull the sock up around your ankle!', 'கணுக்கால் வரை மேலே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (813, 8, 13, 'Smooth the sock around the toes', 'விரல் பகுதியில் காலுறையை நேராக்கவும்', 'Child smooths toe fabric flat.', 'விரல் பகுதியில் உள்ள சுருக்கங்களை நீக்கவும்.', 'Smooth the sock over your toes!', 'விரல் பகுதியை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (814, 8, 14, 'Smooth the sock around the heel', 'குதிக்கால் பகுதியில் காலுறையை நேராக்கவும்', 'Child aligns heel cup snugly.', 'குதிக்கால் சரியாகப் பொருந்துமாறு சரிசெய்யவும்.', 'Make sure the heel fits snug!', 'குதிக்காலை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (815, 8, 15, 'Straighten the sock around the ankle', 'கணுக்காலில் காலுறையை நேராக்கவும்', 'Child flattens upper cuff.', 'கணுக்காலில் உள்ள சுருக்கங்களை நீக்கவும்.', 'Straighten the sock around your ankle!', 'கணுக்காலில் நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (816, 8, 16, 'Check that the heel is correctly positioned', 'குதிக்கால் சரியாக உள்ளதா என சரிபார்க்கவும்', 'Child inspects heel placement.', 'குதிக்கால் வளைவு சரியான இடத்தில் உள்ளதா எனப் பார்க்கவும்.', 'Look at the heel! Fits just right!', 'குதிக்கால் சரியாக உள்ளதா எனப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (817, 8, 17, 'Repeat the same sequence with the other sock', 'மற்றொரு காலிலும் காலுறையை அவ்வாறே அணியவும்', 'Child repeats steps 2 through 16 for opposite foot.', 'மற்றொரு காலுறையையும் அடுத்த காலில் வரிசையாக அணியவும்.', 'Now put the second sock on your other foot!', 'அடுத்த காலுறையையும் அதேபோல் போடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (818, 8, 18, 'Check both socks for correct positioning and comfort', 'இரு காலுறைகளும் சரியாகவும் வசதியாகவும் உள்ளதா எனப் பார்க்கவும்', 'Child verifies comfort on both feet.', 'இரு கால்களிலும் காலுறைகள் வசதியாக உள்ளதை உறுதிசெய்யவும்.', 'Wiggle your toes! Both socks feel super cozy!', 'விரல்களை ஆட்டிப் பார்! காலுறைகள் அருமையாக உள்ளன!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (901, 9, 1, 'Sit in a stable position and look at the shoes', 'நிலையாக அமர்ந்து காலணிகளைப் பார்க்கவும்', 'Child sits securely facing pair of shoes.', 'குழந்தை நிலையாக அமர்ந்து காலணிகளைப் பார்க்க வேண்டும்.', 'Sit steady and look at your shoes!', 'நிலையாக அமர்ந்து காலணிகளைப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (902, 9, 2, 'Identify the right and left shoe', 'வலது மற்றும் இடது காலணியை அடையாளம் காணவும்', 'Child distinguishes left from right shoe orientation.', 'வலது மற்றும் இடது காலணிகளை அடையாளம் காணவும்.', 'Find the right shoe and the left shoe!', 'வலது மற்றும் இடது காலணியைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (903, 9, 3, 'Pick up the correct shoe', 'சரியான காலணியை எடுக்கவும்', 'Child selects shoe corresponding to chosen foot.', 'அணிய வேண்டிய காலணியைக் கையில் எடுக்கவும்.', 'Pick up the shoe for your foot!', 'காலணியை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (904, 9, 4, 'Identify the front and back of the shoe', 'காலணியின் முன்புறம் மற்றும் பின்புறத்தை அறியவும்', 'Child identifies toe box and heel counter.', 'காலணியின் முன் மற்றும் பின் பகுதியை அடையாளம் காணவும்.', 'Find the front toes and back heel of the shoe!', 'முன் விரல் பகுதியையும் பின் குதிக்காலையும் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (905, 9, 5, 'Open the Velcro strap', 'வெல்க்ரோ பட்டையைத் திறக்கவும்', 'Child peels velcro strap open with a pull.', 'வெல்க்ரோ பட்டையை இழுத்துத் திறக்கவும்.', 'Pull the velcro strap open! Rrrrrip!', 'வெல்க்ரோ பட்டையை இழுத்துத் திற!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (906, 9, 6, 'Hold the shoe open', 'காலணியை அகலமாகத் திறந்து பிடிக்கவும்', 'Child holds collar and tongue forward.', 'நாக்குப் பகுதியை முன்னோக்கி இழுத்து அகலமாகப் பிடிக்கவும்.', 'Hold the shoe open wide!', 'காலணியை அகலமாகப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (907, 9, 7, 'Lift the corresponding foot', 'பாதத்தை உயர்த்தவும்', 'Child raises foot to shoe opening.', 'பாதத்தை காலணியின் முன் உயர்த்தவும்.', 'Lift your foot up to the shoe!', 'பாதத்தை மேலே தூக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (908, 9, 8, 'Place the toes into the shoe', 'கால் விரல்களை காலணிக்குள் வைக்கவும்', 'Child inserts toes into front toe box.', 'கால் விரல்களை காலணியின் முன் பகுதிக்குள் வைக்கவும்.', 'Put your toes right into the shoe!', 'விரல்களை உள்ளே வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (909, 9, 9, 'Slide the foot forward into the shoe', 'பாதத்தை காலணிக்குள் முன்னோக்கி தள்ளவும்', 'Child slides foot forward towards toe cap.', 'பாதத்தை காலணிக்குள் முன்னோக்கி நகர்த்தவும்.', 'Slide your foot forward!', 'பாதத்தை முன்னால் தள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (910, 9, 10, 'Push the heel down into the shoe', 'குதிக்காலை காலணிக்குள் கீழே அழுத்தவும்', 'Child presses heel down firmly into shoe bed.', 'குதிக்காலை காலணியின் தரைப்பகுதி வரை கீழே அழுத்தவும்.', 'Push your heel all the way down!', 'குதிக்காலை கீழே அழுத்து!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (911, 9, 11, 'Check that the heel is inside the shoe', 'குதிக்கால் முழுமையாக உள்ளே உள்ளதா என சரிபார்க்கவும்', 'Child verifies heel is fully nested.', 'குதிக்கால் முழுமையாக காலணிக்குள் உள்ளதா எனப் பார்க்கவும்.', 'Make sure your heel is all the way in!', 'குதிக்கால் உள்ளே உள்ளதா எனப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (912, 9, 12, 'Adjust the foot so that it is positioned comfortably', 'பாதம் வசதியாக இருக்குமாறு சரிசெய்யவும்', 'Child wiggles foot into aligned position.', 'பாதம் வலிக்காமல் வசதியாக உள்ளதா என சரிசெய்யவும்.', 'Wiggle your foot so it feels comfortable!', 'பாதத்தை வசதியாக சரிசெய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (913, 9, 13, 'Pull the Velcro strap across the top of the foot', 'வெல்க்ரோ பட்டையை பாதத்தின் மேல் இழுக்கவும்', 'Child pulls strap across instep tightly.', 'வெல்க்ரோ பட்டையை பாதத்தின் குறுக்கே இறுக்கமாக இழுக்கவும்.', 'Pull the velcro strap tight across your foot!', 'பட்டையை குறுக்கே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (914, 9, 14, 'Press the Velcro strap down firmly', 'வெல்க்ரோ பட்டையை உறுதியாக அழுத்தவும்', 'Child presses velcro hook-and-loop together.', 'பட்டையை நன்றாக அழுத்தி ஒட்ட வைக்கவும்.', 'Press the velcro strap down firm!', 'பட்டையை அழுத்தி ஒட்டு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (915, 9, 15, 'Check that the shoe is secure', 'காலணி காலில் உறுதியாக உள்ளதா என சரிபார்க்கவும்', 'Child tugs gently to ensure strap holds.', 'காலணி கழன்று விடாமல் உள்ளதா என உறுதிசெய்யவும்.', 'Make sure the shoe is on tight!', 'காலணி உறுதியாக உள்ளதா எனப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (916, 9, 16, 'Repeat the same sequence with the other shoe', 'மற்றொரு காலணியையும் அவ்வாறே அணியவும்', 'Child repeats procedure for second foot.', 'மற்றொரு காலணியையும் அடுத்த காலில் வரிசையாக அணியவும்.', 'Now put on your other shoe the same way!', 'அடுத்த காலணியையும் அதேபோல் போடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (917, 9, 17, 'Check that both shoes are correctly positioned and stand up safely', 'இரு காலணிகளும் சரியாக உள்ளதா எனப் பார்த்து எழுந்து நிற்கவும்', 'Child stands up safely and tests balance.', 'பாதுகாப்பாக எழுந்து நின்று இரு காலணிகளையும் பார்க்கவும்.', 'Stand up tall and steady on both feet!', 'எழுந்து நேராக நில்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (918, 9, 18, 'Check that both shoes feel comfortable and secure', 'இரு காலணிகளும் வசதியாகவும் சரியாகவும் உள்ளதா என உறுதிசெய்யவும்', 'Child takes test steps.', 'நடந்து பார்த்து இரு காலணிகளும் வசதியாக உள்ளதை உறுதிசெய்யவும்.', 'Stomp your feet! You are ready to walk and play!', 'குதித்துப் பார்! காலணிகள் சூப்பராக உள்ளன!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2601, 26, 1, 'Sit in a stable position and look at the shoes', 'நிலையாக அமர்ந்து காலணிகளைப் பார்க்கவும்', 'Child sits steadily facing pair of slip-on shoes.', 'குழந்தை நிலையாக அமர்ந்து ஸ்லிப்-ஆன் காலணிகளைப் பார்க்க வேண்டும்.', 'Sit steady and look at your slip-on shoes!', 'நிலையாக அமர்ந்து காலணிகளைப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2602, 26, 2, 'Identify the right and left shoe', 'வலது மற்றும் இடது காலணியை அடையாளம் காணவும்', 'Child distinguishes right and left orientation.', 'வலது மற்றும் இடது காலணிகளை அடையாளம் காணவும்.', 'Find the right shoe and the left shoe!', 'வலது மற்றும் இடது காலணியைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2603, 26, 3, 'Pick up the correct shoe', 'சரியான காலணியை எடுக்கவும்', 'Child lifts shoe for chosen foot.', 'அணிய வேண்டிய காலணியைக் கையில் எடுக்கவும்.', 'Pick up the shoe for your foot!', 'காலணியை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2604, 26, 4, 'Identify the front of the shoe', 'காலணியின் முன்புறத்தை அடையாளம் காணவும்', 'Child locates front toe area.', 'காலணியின் முன் விரல் பகுதியைக் கண்டறியவும்.', 'Find the front where your toes go!', 'முன்பக்கத்தைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2605, 26, 5, 'Hold the shoe open', 'காலணியை இரு கைகளாலும் திறந்து பிடிக்கவும்', 'Child holds sides of opening.', 'காலணியின் திறப்புப் பகுதியை இரு கைகளாலும் பிடிக்கவும்.', 'Hold the shoe collar open!', 'காலணியைத் திறந்து பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2606, 26, 6, 'Lift the corresponding foot', 'பாதத்தை உயர்த்தவும்', 'Child brings foot to shoe entrance.', 'பாதத்தை காலணியின் முன் உயர்த்தவும்.', 'Lift your foot up to the shoe!', 'பாதத்தை மேலே தூக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2607, 26, 7, 'Place the toes into the shoe', 'கால் விரல்களை காலணிக்குள் வைக்கவும்', 'Child guides toes in.', 'கால் விரல்களை காலணிக்குள் வைக்கவும்.', 'Put your toes inside the shoe!', 'விரல்களை உள்ளே வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2608, 26, 8, 'Slide the foot forward', 'பாதத்தை முன்னோக்கி தள்ளவும்', 'Child glides foot into front of shoe.', 'பாதத்தை காலணிக்குள் முன்னோக்கி நகர்த்தவும்.', 'Slide your foot forward!', 'பாதத்தை முன்னால் தள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2609, 26, 9, 'Push the heel down into the shoe', 'குதிக்காலை காலணிக்குள் கீழே அழுத்தவும்', 'Child presses heel firmly into shoe.', 'குதிக்காலை காலணியின் தரைப்பகுதி வரை கீழே அழுத்தவும்.', 'Push your heel down in!', 'குதிக்காலை கீழே அழுத்து!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2610, 26, 10, 'Check that the entire foot is inside', 'முழுப் பாதமும் காலணிக்குள் உள்ளதா எனப் பார்க்கவும்', 'Child confirms heel and foot are fully seated.', 'முழுப் பாதமும் உள்ளே சென்றுள்ளதை உறுதிசெய்யவும்.', 'Make sure your whole foot is inside!', 'பாதம் முழுமையாக உள்ளே உள்ளதா எனப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2611, 26, 11, 'Adjust the shoe if necessary', 'தேவைப்பட்டால் காலணியை சரிசெய்யவும்', 'Child pulls back tab or adjusts fit.', 'தேவைப்பட்டால் காலணியின் பின் பகுதியை சரிசெய்யவும்.', 'Fix the back if you need to!', 'பின்பக்கத்தை சரிசெய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2612, 26, 12, 'Repeat with the other shoe', 'மற்றொரு காலணியையும் அவ்வாறே அணியவும்', 'Child puts second slip-on shoe on.', 'மற்றொரு காலணியையும் அடுத்த காலில் அணியவும்.', 'Now put on the other shoe!', 'அடுத்த காலணியையும் போடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2613, 26, 13, 'Check that both shoes are correctly positioned, stand safely, and are comfortable', 'இரு காலணிகளும் வசதியாகவும் சரியாகவும் உள்ளதா எனப் பார்க்கவும்', 'Child stands and confirms comfort.', 'எழுந்து நின்று இரு காலணிகளும் வசதியாக உள்ளதை உறுதிசெய்யவும்.', 'All slipped on! Walk around, you are ready!', 'காலணிகள் போட்டாச்சு! அருமை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1001, 10, 1, 'Sit in a stable position', 'நிலையாக அமரவும்', 'Child sits securely.', 'குழந்தை நிலையாக அமர வேண்டும்.', 'Sit nice and steady!', 'நிலையாக அமர்ந்து கொள்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1002, 10, 2, 'Identify the right and left shoe', 'வலது மற்றும் இடது காலணியை அடையாளம் காணவும்', 'Child distinguishes right and left shoe.', 'வலது மற்றும் இடது காலணிகளை அடையாளம் காணவும்.', 'Find the right shoe and the left shoe!', 'வலது மற்றும் இடது காலணியைக் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1003, 10, 3, 'Pick up the correct shoe', 'சரியான காலணியை எடுக்கவும்', 'Child selects appropriate shoe.', 'அணிய வேண்டிய காலணியை எடுக்கவும்.', 'Pick up your shoe!', 'காலணியை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1004, 10, 4, 'Loosen/open the shoelaces sufficiently', 'காலணிக் கயிறுகளை தளர்த்தவும்', 'Child loosens laces and pulls tongue forward.', 'கயிறுகளை தளர்த்தி நாக்குப் பகுதியை முன்னோக்கி இழுக்கவும்.', 'Loosen up the laces so it opens wide!', 'கயிறுகளை தளர்த்தி அகலமாக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1005, 10, 5, 'Hold the shoe open', 'காலணியைத் திறந்து பிடிக்கவும்', 'Child holds collar open.', 'காலணியின் திறப்புப் பகுதியை அகலமாகப் பிடிக்கவும்.', 'Hold the shoe open with both hands!', 'இரு கைகளாலும் காலணியைத் திறந்து பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1006, 10, 6, 'Place the toes into the shoe', 'கால் விரல்களை காலணிக்குள் வைக்கவும்', 'Child slides toes into opening.', 'கால் விரல்களை காலணிக்குள் வைக்கவும்.', 'Put your toes in!', 'விரல்களை உள்ளே வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1007, 10, 7, 'Slide the foot forward', 'பாதத்தை முன்னோக்கி தள்ளவும்', 'Child pushes foot forward into toe box.', 'பாதத்தை காலணிக்குள் முன்னோக்கி நகர்த்தவும்.', 'Slide your foot all the way forward!', 'பாதத்தை முன்னால் தள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1008, 10, 8, 'Push the heel down', 'குதிக்காலை கீழே அழுத்தவும்', 'Child pushes heel into rear footbed.', 'குதிக்காலை காலணிக்குள் கீழே அழுத்தவும்.', 'Push your heel down into the shoe!', 'குதிக்காலை கீழே அழுத்து!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1009, 10, 9, 'Adjust the tongue of the shoe', 'காலணியின் நாக்குப் பகுதியை நேராக்கவும்', 'Child pulls tongue flat against instep.', 'நாக்குப் பகுதியை சுருக்கமின்றி நேராக இழுத்து விடவும்.', 'Pull the tongue straight and flat!', 'நாக்குப் பகுதியை நேராக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1010, 10, 10, 'Pull the laces to adjust the shoe', 'கயிறுகளை இழுத்து காலணியை இறுக்கவும்', 'Child pulls criss-cross laces snug.', 'கயிறுகளை இழுத்து பாதம் நன்கு பொருந்துமாறு இறுக்கவும்.', 'Pull the laces snug around your foot!', 'கயிறுகளை இழுத்து இறுக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1011, 10, 11, 'Tie the shoelaces securely', 'காலணிக் கயிறுகளை முடிச்சுப் போடவும்', 'Child ties knots and loops.', 'கயிறுகளை சுருக்குப் போட்டு முடிச்சு கட்டவும்.', 'Tie up your laces with a nice knot!', 'கயிறுகளை முடிச்சு போடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1012, 10, 12, 'Repeat with the other shoe', 'மற்றொரு காலணியையும் அவ்வாறே அணியவும்', 'Child puts on second lace-up shoe.', 'மற்றொரு காலணியையும் அடுத்த காலில் அணியவும்.', 'Now put on your other lace shoe!', 'அடுத்த காலணியையும் போடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1013, 10, 13, 'Check that both shoes are comfortable and secure', 'இரு காலணிகளும் வசதியாகவும் சரியாகவும் உள்ளதா என உறுதிசெய்யவும்', 'Child stands and verifies fit.', 'எழுந்து நின்று இரு காலணிகளும் வசதியாக உள்ளதை உறுதிசெய்யவும்.', 'Laced up tight and ready to run!', 'கயிறு கட்டியாச்சு! விளையாடப் போகலாம்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2701, 27, 1, 'Find both laces', 'இரு கயிறுகளையும் கண்டறியவும்', 'Child locates left and right shoe laces.', 'இடது மற்றும் வலது கயிறுகளை அடையாளம் காணவும்.', 'Find both of your shoelaces!', 'இரு காலணிக் கயிறுகளையும் கண்டுபிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2702, 27, 2, 'Hold one lace in each hand', 'ஒவ்வொரு கையிலும் ஒரு கயிற்றைப் பிடிக்கவும்', 'Child grips left lace in left hand, right lace in right hand.', 'ஒவ்வொரு கையிலும் ஒரு கயிற்றைப் பிடிக்கவும்.', 'Hold one lace in each hand!', 'இரு கைகளிலும் கயிறுகளைப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2703, 27, 3, 'Cross the laces', 'கயிறுகளை குறுக்காக வைக்கவும்', 'Child crosses laces to make an X.', 'கயிறுகளை ஒன்றன் மேல் ஒன்றாக குறுக்காக வைக்கவும்.', 'Cross the laces to make a big X!', 'கயிறுகளை குறுக்காக வை! X போல!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2704, 27, 4, 'Make the first knot', 'முதல் முடிச்சை உருவாக்கவும்', 'Child tucks one lace under and pulls tight.', 'ஒரு கயிற்றை கீழே நுழைத்து இழுத்து முதல் முடிச்சு போடவும்.', 'Tuck one under and pull tight for the first knot!', 'கீழே நுழைத்து இழு! முதல் முடிச்சு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2705, 27, 5, 'Make one loop', 'ஒரு சுருக்கு வளையம் செய்யவும்', 'Child folds one lace into a loop (bunny ear).', 'ஒரு கயிற்றில் முயல் காது போல சிறிய வளையம் செய்யவும்.', 'Make a loop like a bunny ear!', 'ஒரு முயல் காது வளையம் செய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2706, 27, 6, 'Wrap the other lace around the loop', 'மற்றொரு கயிற்றை வளையத்தைச் சுற்றி சுற்றவும்', 'Child winds second lace around base of loop.', 'மற்றொரு கயிற்றை அந்த வளையத்தைச் சுற்றி சுற்றவும்.', 'Wrap the other lace all the way around the loop!', 'சுற்றி வளைத்து எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2707, 27, 7, 'Push the lace through', 'கயிற்றை துளை வழியே தள்ளவும்', 'Child pushes middle of wrapped lace through opening.', 'கயிற்றை துளை வழியே தள்ளி வெளியே கொண்டு வரவும்.', 'Push the lace through the little hole!', 'துளை வழியே உள்ளே தள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2708, 27, 8, 'Make the second loop', 'இரண்டாவது வளையத்தை உருவாக்கவும்', 'Child grasps the emerging second loop.', 'இரண்டாவது வளையத்தைப் பிடித்து வெளியே இழுக்கவும்.', 'Pull the second bunny ear out!', 'இரண்டாவது முயல் காதை வெளியே இழு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2709, 27, 9, 'Pull both loops tight', 'இரு வளையங்களையும் இறுக்கமாக இழுக்கவும்', 'Child pulls both loops outward until snug.', 'இரு வளையங்களையும் பக்கவாட்டில் இழுத்து முடிச்சை இறுக்கவும்.', 'Pull both loops tight, tight, tight!', 'இரு வளையங்களையும் இழுத்து இறுக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (2710, 27, 10, 'Check your shoelace', 'காலணிக் கயிற்றைச் சரிபார்க்கவும்', 'Child confirms knot is secure.', 'முடிச்சு அவிழாமல் உறுதியாக உள்ளதா என சரிபார்க்கவும்.', 'Look at your beautiful bow! You tied your shoes!', 'அழகான முடிச்சு போட்டாச்சு! சபாஷ்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1101, 11, 1, 'Sit upright at the table', 'மேஜையில் நேராக அமரவும்', 'Child takes stable upright posture in chair.', 'குழந்தை நாற்காலியில் மேஜை முன் நேராக அமர வேண்டும்.', 'Sit up tall and straight at the table!', 'மேஜை முன் நேராக அமர்ந்து கொள்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1102, 11, 2, 'Position the plate within comfortable reach and look at the rice and gravy', 'தட்டை வசதியாக வைத்து உணவைப் பார்க்கவும்', 'Child positions food plate within forearm reach.', 'தட்டை கைகளுக்கு எட்டும் தூரத்தில் வைத்து உணவைப் பார்க்கவும்.', 'Put your plate in front of you and look at the yummy food!', 'தட்டை எட்டும் தூரத்தில் வைத்துப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1103, 11, 3, 'Take an appropriate amount of rice using the fingers', 'விரல்களால் தேவையான அளவு சாதத்தை எடுக்கவும்', 'Child uses fingers to gather small mound of rice.', 'கை விரல்களால் ஒரு பிடி சாதத்தை தனியாக எடுக்கவும்.', 'Gather a small portion of rice with your fingers!', 'விரல்களால் கொஞ்சம் சாதத்தை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1104, 11, 4, 'Add an appropriate amount of gravy/curry', 'தேவையான அளவு குழம்பைச் சேர்க்கவும்', 'Child pulls curry over to the rice portion.', 'தேவையான அளவு குழம்பை அந்த சாதத்தோடு சேர்க்கவும்.', 'Mix a little bit of gravy into your rice!', 'கொஞ்சம் குழம்பை சாதத்தில் சேர்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1105, 11, 5, 'Mix the rice and gravy using the fingers', 'விரல்களால் சாதமும் குழம்பும் பிசையவும்', 'Child uses fingers to blend rice and gravy together.', 'விரல்களால் சாதத்தையும் குழம்பையும் நன்றாகப் பிசையவும்.', 'Mix the rice and gravy nicely together!', 'சாதத்தையும் குழம்பையும் பிசை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1106, 11, 6, 'Gather an appropriate-sized portion of the mixed rice', 'பிசைந்த சாதத்தை வாய் அளவிற்கு உருட்டவும்', 'Child gathers a bite-sized portion.', 'ஒரு வாய் அளவிற்கு தேவையான சாதத்தை விரல்களால் ஒன்றாகச் சேர்க்கவும்.', 'Gather a nice bite-sized portion!', 'ஒரு வாய் அளவு சாதத்தை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1107, 11, 7, 'Shape/gather the food using the fingers and palm as appropriate', 'விரல்களால் சாதத்தை உருட்டிப் பிடிக்கவும்', 'Child shapes portion into manageable morsel.', 'விரல்களின் உதவியுடன் சாதத்தை சிறிய உருண்டையாக உருட்டவும்.', 'Shape it into a neat little bite with your fingers!', 'விரல்களால் சாதத்தை உருண்டை செய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1108, 11, 8, 'Bring the food toward the mouth and open the mouth', 'உணவை வாயின் அருகில் கொண்டு வந்து வாயைத் திறக்கவும்', 'Child moves hand smoothly to open mouth.', 'உணவை வாயின் அருகில் கொண்டு வந்து வாயை அகலத் திறக்கவும்.', 'Bring the food to your mouth and open wide! Ahh!', 'உணவை வாயருகே கொண்டு வா! வாயைத் திற! ஆ!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1109, 11, 9, 'Place the food into the mouth and move the hand away from the mouth', 'உணவை வாயில் வைத்து கையை எடுக்கவும்', 'Child deposits food using thumb push without touching lips with whole palm.', 'உணவை வாய்க்குள் வைத்து கையை வாயிலிருந்து அகற்றவும்.', 'Put the food in your mouth and move your hand back!', 'உணவை வாயில் வைத்து கையை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1110, 11, 10, 'Chew and swallow the food', 'உணவை மென்று விழுங்கவும்', 'Child closes mouth, chews thoroughly, and swallows.', 'வாயை மூடி உணவை நன்றாக மென்று விழுங்கவும்.', 'Chew your food nicely and swallow!', 'நன்றாக மென்று விழுங்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1111, 11, 11, 'Return the hand to the plate', 'கையை மீண்டும் தட்டிற்கு கொண்டு வரவும்', 'Child rests hand back near plate.', 'கையை மீண்டும் தட்டின் பக்கம் கொண்டு வரவும்.', 'Bring your hand back down to your plate!', 'கையை தட்டின் பக்கம் கொண்டு வா!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1112, 11, 12, 'Repeat the sequence with the next portion', 'அடுத்த பிடி உணவிற்கும் அவ்வாறே செய்யவும்', 'Child gathers subsequent bite.', 'அடுத்த பிடி சாதத்தையும் குழம்புடன் சேர்த்து பிசைந்து எடுக்கவும்.', 'Now gather your next yummy bite!', 'அடுத்த பிடி சாதத்தை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1113, 11, 13, 'Continue until the appropriate amount of food is eaten', 'போதுமான அளவு உணவு சாப்பிடும் வரை தொடரவும்', 'Child continues eating self-paced meal.', 'வயிறு நிறையும் வரை முறையாக சாப்பிட்டு முடிக்கவும்.', 'Keep eating until your tummy is happy and full!', 'வயிறு நிறையும் வரை சாப்பிடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1114, 11, 14, 'Wipe/clean the hands', 'கைகளைத் துடைத்து சுத்தம் செய்யவும்', 'Child washes or wipes fingers with napkin.', 'சாப்பிட்டு முடித்ததும் கைகளைத் துடைத்து கழுவவும்.', 'Clean your hands with water and a towel! All done!', 'கைகளை நன்றாகக் கழுவித் துடைத்து விடு! அருமை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1201, 12, 1, 'Position the plate within comfortable reach and look at the breakfast item', 'தட்டை வசதியாக வைத்து சிற்றுண்டியைப் பார்க்கவும்', 'Child sits upright facing idli/dosa/roti.', 'குழந்தை நேராக அமர்ந்து தட்டில் உள்ள இட்லி, தோசையைப் பார்க்க வேண்டும்.', 'Sit upright and look at your delicious breakfast!', 'நேராக அமர்ந்து சிற்றுண்டியைப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1202, 12, 2, 'Reach toward the food with the preferred hand', 'விருப்பமான கையால் உணவை நோக்கி நீட்டவும்', 'Child extends preferred eating hand.', 'சாப்பிடும் கையை உணவு தட்டை நோக்கி நீட்டவும்.', 'Reach your hand toward the food!', 'கையை தட்டின் பக்கம் கொண்டு வா!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1203, 12, 3, 'Pick up the food or an appropriate portion', 'உணவின் ஒரு பகுதியை எடுக்கவும்', 'Child grasps edge of breakfast food.', 'உணவின் ஒரு விளிம்பை விரல்களால் பிடிக்கவும்.', 'Pick up a piece of the food!', 'உணவின் ஒரு பகுதியை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1204, 12, 4, 'Break the food into a manageable-sized piece when required', 'உணவை தேவையான சிறிய துண்டாகப் பிய்க்கவும்', 'Child uses fingers to tear off bite-sized morsel.', 'கை விரல்களால் ஒரு வாய் அளவிற்கு உணவைப் பிய்க்கவும்.', 'Tear off a small bite-sized piece!', 'சிறிய துண்டாகப் பிய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1205, 12, 5, 'Hold the food securely using the fingers', 'விரல்களால் உணவை உறுதியாகப் பிடிக்கவும்', 'Child secures piece between thumb and fingers.', 'பிய்த்த உணவை விரல்களுக்கு இடையே கெட்டியாகப் பிடிக்கவும்.', 'Hold the piece securely with your fingers!', 'விரல்களால் உணவைப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1206, 12, 6, 'Add or dip into an appropriate accompaniment such as chutney or sambar, when applicable', 'சட்னி அல்லது சாம்பாரில் தொட்டு எடுக்கவும்', 'Child dips food lightly into chutney/sambar.', 'உணவை சட்னி அல்லது சாம்பாரில் தொட்டு எடுக்கவும்.', 'Dip your food into the yummy chutney or sambar!', 'சட்னி அல்லது சாம்பாரில் தொடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1207, 12, 7, 'Bring the food toward the mouth and open the mouth', 'உணவை வாயருகே கொண்டு வந்து வாயைத் திறக்கவும்', 'Child transports food to open mouth.', 'உணவை வாயின் அருகில் கொண்டு வந்து வாயைத் திறக்கவும்.', 'Bring the food to your mouth and open wide! Ahh!', 'உணவை வாயருகே கொண்டு வா! வாயைத் திற!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1208, 12, 8, 'Place the food into the mouth', 'உணவை வாய்க்குள் வைக்கவும்', 'Child places food onto tongue.', 'உணவை வாய்க்குள் மெதுவாக வைக்கவும்.', 'Put the bite into your mouth!', 'உணவை வாயில் வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1209, 12, 9, 'Move the hand away from the mouth', 'கையை வாயிலிருந்து அகற்றவும்', 'Child releases food and moves hand down.', 'உணவை வாயில் வைத்ததும் கையை வெளியே கொண்டு வரவும்.', 'Move your hand away!', 'கையை வெளியே எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1210, 12, 10, 'Chew and swallow the food', 'உணவை மென்று விழுங்கவும்', 'Child chews food well and swallows.', 'உணவை நன்றாக மென்று விழுங்கவும்.', 'Chew, chew, chew, and swallow!', 'மென்று விழுங்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1211, 12, 11, 'Return the hand toward the plate', 'கையை மீண்டும் தட்டின் பக்கம் கொண்டு வரவும்', 'Child positions hand for next piece.', 'கையை மீண்டும் தட்டின் பக்கம் கொண்டு வரவும்.', 'Rest your hand by the plate!', 'கையை தட்டின் பக்கம் வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1212, 12, 12, 'Pick up the next appropriate portion', 'அடுத்த துண்டு உணவை எடுக்கவும்', 'Child prepares next bite.', 'அடுத்த துண்டு உணவை பிய்த்து எடுக்கவும்.', 'Break off the next piece!', 'அடுத்த துண்டைப் பிய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1213, 12, 13, 'Repeat the sequence until the appropriate amount is eaten', 'சாப்பிட்டு முடிக்கும் வரை தொடரவும்', 'Child finishes meal self-paced.', 'வயிறு நிறையும் வரை முறையாக சாப்பிட்டு முடிக்கவும்.', 'Keep eating until your tummy is happy!', 'வயிறு நிறையும் வரை சாப்பிடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1214, 12, 14, 'Clean/wipe the hands', 'கைகளைத் துடைத்து சுத்தம் செய்யவும்', 'Child washes or wipes mouth and hands.', 'சாப்பிட்டதும் கைகளையும் வாயையும் சுத்தமாகத் துடைக்கவும்.', 'Wash and dry your hands! You did wonderful!', 'கைகளைக் கழுவித் துடைத்து விடு! மிக அருமை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1301, 13, 1, 'Sit upright at the table', 'மேஜையில் நேராக அமரவும்', 'Child sits upright with elbows relaxed.', 'குழந்தை நாற்காலியில் மேஜை முன் நேராக அமர வேண்டும்.', 'Sit up tall and straight at the table!', 'மேஜை முன் நேராக அமர்ந்து கொள்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1302, 13, 2, 'Position the bowl/plate within comfortable reach and look at the food', 'கிண்ணத்தை வசதியாக வைத்து உணவைப் பார்க்கவும்', 'Child centers bowl on table and looks at food.', 'உணவு உள்ள கிண்ணத்தை எட்டும் தூரத்தில் வைத்து உணவைப் பார்க்கவும்.', 'Place your bowl in front and look at the food!', 'கிண்ணத்தை முன்னால் வைத்துப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1303, 13, 3, 'Pick up the spoon using the preferred hand', 'விருப்பமான கையால் கரண்டியை எடுக்கவும்', 'Child grasps spoon handle.', 'கரண்டியை கையில் எடுக்கவும்.', 'Pick up your spoon!', 'கரண்டியை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1304, 13, 4, 'Hold the spoon securely', 'கரண்டியை உறுதியாகப் பிடிக்கவும்', 'Child establishes palmar or digital grasp on handle.', 'கரண்டியின் கைப்பிடியை விரல்களால் கெட்டியாகப் பிடிக்கவும்.', 'Hold the spoon handle tight in your hand!', 'கரண்டியை உறுதியாகப் பிடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1305, 13, 5, 'Bring the spoon toward the food', 'கரண்டியை உணவை நோக்கி கொண்டு வரவும்', 'Child moves spoon bowl over dish.', 'கரண்டியை உணவு உள்ள கிண்ணத்தை நோக்கிக் கொண்டு வரவும்.', 'Bring the spoon over to your food!', 'கரண்டியை உணவின் பக்கம் கொண்டு வா!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1306, 13, 6, 'Place the spoon into the food', 'கரண்டியை உணவுக்குள் வைக்கவும்', 'Child lowers bowl of spoon into food.', 'கரண்டியின் குழியை உணவுக்குள் இறக்கவும்.', 'Lower the spoon into the food!', 'கரண்டியை உணவுக்குள் இறக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1307, 13, 7, 'Scoop an appropriate amount of food', 'தேவையான அளவு உணவை அள்ளவும்', 'Child scoops food without overloading.', 'சிந்தாதவாறு தேவையான அளவு உணவை கரண்டியில் அள்ளவும்.', 'Scoop up a yummy spoonful!', 'ஒரு கரண்டி உணவை அள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1308, 13, 8, 'Lift the spoon while keeping the food on it', 'உணவு சிந்தாமல் கரண்டியை உயர்த்தவும்', 'Child lifts spoon horizontally without tilting.', 'உணவு கீழே சிந்தாமல் கரண்டியை நேராக மேலே உயர்த்தவும்.', 'Lift the spoon carefully so it does not spill!', 'சிந்தாமல் கரண்டியை மேலே தூக்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1309, 13, 9, 'Move the spoon toward the mouth and open your mouth', 'கரண்டியை வாயருகே கொண்டு வந்து வாயைத் திறக்கவும்', 'Child transports spoon level and opens mouth.', 'கரண்டியை வாயின் அருகில் கொண்டு வந்து வாயைத் திறக்கவும்.', 'Bring the spoon up to your mouth and open wide!', 'கரண்டியை வாயருகே கொண்டு வா! வாயைத் திற!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1310, 13, 10, 'Place the spoon into the mouth', 'கரண்டியை வாய்க்குள் வைக்கவும்', 'Child places spoon bowl over tongue.', 'கரண்டியை வாய்க்குள் மெதுவாக வைக்கவும்.', 'Put the spoon gently in your mouth!', 'கரண்டியை வாயில் வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1311, 13, 11, 'Close the lips around the spoon', 'கரண்டியின் மேல் உதடுகளை மூடவும்', 'Child seals upper lip over spoon bowl to clear food.', 'கரண்டியில் உள்ள உணவை எடுக்க உதடுகளை மூடவும்.', 'Close your lips over the spoon to take the food!', 'உதடுகளை மூடி உணவை எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1312, 13, 12, 'Remove the spoon from the mouth', 'கரண்டியை வாயிலிருந்து வெளியே எடுக்கவும்', 'Child withdraws spoon horizontally.', 'கரண்டியை வாயிலிருந்து வெளியே எடுக்கவும்.', 'Take the spoon out of your mouth!', 'கரண்டியை வெளியே எடு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1313, 13, 13, 'Keep the food in the mouth', 'உணவை வாய்க்குள் வைத்திருக்கவும்', 'Child retains food bolus in oral cavity.', 'உணவை சிந்தாமல் வாய்க்குள் வைத்திருக்கவும்.', 'Keep the yummy food inside your mouth!', 'உணவை வாய்க்குள் வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1314, 13, 14, 'Chew the food as needed', 'உணவை நன்றாக மெல்லவும்', 'Child masticates food thoroughly.', 'உணவை பற்களால் நன்றாக மெல்லவும்.', 'Chew your food nicely!', 'நன்றாக மெல்லு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1315, 13, 15, 'Swallow the food', 'உணவை விழுங்கவும்', 'Child swallows food completely.', 'உணவை முழுமையாக விழுங்கவும்.', 'Swallow the food down!', 'உணவை விழுங்கு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1316, 13, 16, 'Lower the spoon toward the bowl/plate', 'கரண்டியை மீண்டும் கிண்ணத்தை நோக்கி இறக்கவும்', 'Child lowers empty spoon to food dish.', 'கரண்டியை மீண்டும் கிண்ணத்தை நோக்கி கீழே இறக்கவும்.', 'Lower your spoon back to the bowl!', 'கரண்டியை மீண்டும் கிண்ணத்துக்குக் கொண்டு வா!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1317, 13, 17, 'Scoop the next appropriate amount of food', 'அடுத்த வாய் உணவை அள்ளவும்', 'Child scoops second bite.', 'அடுத்த வாய் உணவை கரண்டியில் அள்ளவும்.', 'Scoop up another delicious bite!', 'அடுத்த வாய் உணவை அள்ளு!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1318, 13, 18, 'Repeat the sequence until the desired portion is eaten', 'சாப்பிட்டு முடிக்கும் வரை தொடரவும்', 'Child continues spoon feeding independently.', 'வயிறு நிறையும் வரை கரண்டியால் சாப்பிட்டு முடிக்கவும்.', 'Keep eating until your bowl is clean!', 'முழுமையாக சாப்பிட்டு முடி!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1319, 13, 19, 'Place the spoon down when finished', 'சாப்பிட்டு முடித்ததும் கரண்டியை கீழே வைக்கவும்', 'Child rests spoon on plate or table.', 'சாப்பிட்டு முடித்ததும் கரண்டியை தட்டில் வைக்கவும்.', 'Put your spoon down on the table!', 'கரண்டியை கீழே வை!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1320, 13, 20, 'Check that the eating area is reasonably clean', 'சாப்பிட்ட இடத்தை சரிபார்க்கவும்', 'Child checks table for dropped food.', 'சாப்பிட்ட மேஜை சுத்தமாக உள்ளதா எனப் பார்க்கவும்.', 'Look at the table! Nice and clean!', 'மேஜை சுத்தமாக உள்ளதா எனப் பார்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
INSERT INTO task_steps (id, activity_id, step_number, title, title_ta, instruction_text, instruction_text_ta, child_instruction, child_instruction_ta) VALUES (1321, 13, 21, 'Wipe the mouth/hands if needed', 'வாய் மற்றும் கைகளைத் துடைக்கவும்', 'Child uses napkin to clean mouth and hands.', 'வாய் மற்றும் கைகளை நாப்கினால் சுத்தமாகத் துடைக்கவும்.', 'Wipe your mouth and smile! Super job with the spoon!', 'வாயைத் துடைத்து சிரி! அருமையாக சாப்பிட்டாய்!') ON DUPLICATE KEY UPDATE step_number = VALUES(step_number), title = VALUES(title), title_ta = VALUES(title_ta), instruction_text = VALUES(instruction_text), instruction_text_ta = VALUES(instruction_text_ta), child_instruction = VALUES(child_instruction), child_instruction_ta = VALUES(child_instruction_ta);
